const sceneParam = new URLSearchParams(location.search).get('escena'); // FIX: ?escena=stage permite previsualizar camino y personajes en modo capas (para enchufar el arte nuevo).
if (sceneParam === 'stage') { SCENES.camino.layout = 'stage'; SCENES.personajes.layout = 'stage'; }

// FIX: pinta una escena con su imagen y sus capas posicionadas en %; con crop solo se muestra una zona, pero las capas siguen usando coordenadas de la imagen completa.
function renderStage(id, extra = '') {
  const scene = SCENES[id]; const crop = scene.crop || { x: 0, y: 0, w: 100, h: 100 }; const [iw, ih] = scene.ratio;
  const imgStyle = `width:${10000 / crop.w}%;left:${-crop.x * 100 / crop.w}%;top:${-crop.y * 100 / crop.h}%`;
  const layers = (scene.layers || []).filter(layer => layer.cover || !(scene.baked && layer.painted)).map(layer => {
    const left = (layer.x - crop.x) * 100 / crop.w, top = (layer.y - crop.y) * 100 / crop.h;
    const style = `left:${left}%;top:${top}%;${layer.w ? `width:${layer.w * 100 / crop.w}%;` : ''}${layer.h ? `height:${layer.h * 100 / crop.h}%;` : ''}${layer.size ? `font-size:${layer.size}cqw;` : ''}`;
    const tag = layer.action ? 'button' : 'div';
    return `<${tag} class="layer layer-${layer.type} ${layer.cls || ''}" style="${style}"${layer.action ? ` data-action="${layer.action}"` : ''}><span>${layer.text}</span></${tag}>`;
  }).join('');
  return `<div class="stage stage-${id}" style="aspect-ratio:${crop.w * iw}/${crop.h * ih}"><img class="stage-img" src="${scene.img}" alt="" style="${imgStyle}">${layers}${extra}</div>`;
}
function bindActions(root = document) { root.querySelectorAll('[data-action]').forEach(button => button.onclick = () => runAction(button.dataset.action, button)); }
function runAction(action, button) {
  const [kind, value] = action.split(':');
  if (kind === 'hotspot') hotspot(value);
  else if (kind === 'character') pickCharacter(value);
  else if (kind === 'path') pickPath(Number(value));
  else if (kind === 'close') closeModal();
  else if (kind === 'toggle') { const target = document.getElementById(value); if (target) { target.classList.toggle('show'); button.setAttribute('aria-expanded', target.classList.contains('show')); } }
}

// FIX: guardado local (localStorage) sin datos personales: solo el progreso del juego. try/catch porque algunos navegadores bloquean el almacenamiento en file://.
const SAVE_KEY = 'vida-aborigen-partida-v1';
function save() { try { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch (error) { /* sin almacenamiento: se juega igual, sin guardar */ } }
function loadSave() { try { const saved = JSON.parse(localStorage.getItem(SAVE_KEY)); return saved && saved.character ? saved : null; } catch (error) { return null; } }
function clearSave() { try { localStorage.removeItem(SAVE_KEY); } catch (error) { /* nada que borrar */ } }

// FIX: ya no muestra «· null» antes de elegir personaje (L15 original); además guarda la partida en cada actualización del marcador.
function setHUD() { $('#pathName').textContent = state.path ? [state.path.title, state.character].filter(Boolean).join(' · ') : 'Sin elegir'; $('#knowledge').textContent = state.knowledge; $('#day').textContent = state.day; $('#itemCount').textContent = `${Object.values(state.items).filter(Boolean).length}/${resources.length}`; /* FIX: el total sale de la lista de recursos (ahora 10) */ renderPocket(); /* FIX (fase 4): casillas del bolsillo en el marcador */ if ($('#season')) $('#season').textContent = SEASONS[season()]; /* FIX (fase 6): estación en el marcador */ if (state.character) save(); }
let toastTimer; // FIX: un toast nuevo reinicia el temporizador (antes se ocultaba antes de tiempo si se encadenaban dos).
function toast(message) { const element = $('#toast'); element.textContent = message; element.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => element.classList.remove('show'), 2300); }
// FIX: el fondo de cada pantalla sale de SCENES (antes estaba fijado en styles.css), para poder cambiar el arte sin tocar el CSS.
function go(html, className = '', sceneId = null) { pocketHandler = null; /* FIX (fase 4): cada pantalla define el uso del bolsillo */ const sc = sceneId && SCENES[sceneId]; screen.className = `screen ${className}${sc && sc.panel ? ` panel-${sc.panel}` : ''}${sc && sc.night ? ' scene-night' : ''}`; /* FIX (final): colocación del panel según la escena */ screen.style.backgroundImage = sceneId && SCENES[sceneId] ? `url("${SCENES[sceneId].img}")` : ''; screen.innerHTML = html; window.scrollTo(0, 0); setHUD(); bindActions(screen); measureChrome(); }
// FIX: ventana accesible: foco inicial en «×», Escape la cierra y el foco vuelve al botón que la abrió.
let lastFocus = null;
function openModal(body, size = '') { lastFocus = document.activeElement; $('.modal-card').classList.toggle('wide', size === 'wide'); $('#modalBody').innerHTML = body; $('#modal').classList.remove('hidden'); bindActions($('#modalBody')); $('#closeModal').focus(); }
function closeModal() { if ($('#modal').classList.contains('hidden')) return; $('#modal').classList.add('hidden'); if (lastFocus && document.body.contains(lastFocus)) lastFocus.focus(); }
$('#closeModal').onclick = closeModal;
$('#modal').addEventListener('click', event => { if (event.target.id === 'modal') closeModal(); }); // FIX: pulsar fuera de la ventana también la cierra.
document.addEventListener('keydown', event => { if (event.key === 'Escape') closeModal(); }); // FIX: Escape cierra las ventanas.

// FIX: si hay partida guardada, la portada ofrece «Continuar» y «Nueva partida».
function intro() { const saved = loadSave(); go(`<div class="intro"><div class="intro-content"><div class="seal">✦</div><h1>Vida Aborigen</h1><p>La isla cuenta sus historias. Explora, aprende y ayuda a tu comunidad a preparar la gran noche del Almogarén.</p>${saved ? `<button class="parchment-btn start-btn" id="continue">Continuar partida</button> <button class="parchment-btn start-btn secondary-btn" id="start">Nueva partida</button><p class="save-note">Partida guardada en este navegador: ${saved.character}, jornada ${saved.day}, ${saved.knowledge} de saber.</p>` : '<button class="parchment-btn start-btn" id="start">Comenzar viaje</button>'}</div></div>`, '', 'intro'); $('#start').onclick = () => { if (saved && !confirm('¿Empezar de nuevo? Se borrará la partida guardada en este navegador.')) return; clearSave(); resetState(); choosePath(); }; if (saved) $('#continue').onclick = () => { Object.assign(state, saved); resume(); }; }
function resetState() { Object.assign(state, { path: null, pathId: null, character: null, knowledge: 0, day: 1, items: {}, visited: [], confidence: 0, journal: ['comunidad'], done: {}, crafted: {}, gathered: {}, j1Start: 0, j1Done: false, station: 'madera', pocket: [null, null, null], decor: {}, symbols: [...SYM_START], paintMigrated: true, paintSel: [], time: 0, forest: {}, tracks: {}, farm: {}, granary: {}, night: { told: [], heard: {}, sky: {}, stories: 0 } }); /* FIX (fase 7): la noche */ } /* FIX (fase 6): estaciones, monte, rastreo y campos */ // FIX (fase 5): símbolos descubiertos
// FIX (fase 3): partidas guardadas antes de la fase 3: «Banot de viaje» → garrote; planta → mocán; anzuelo regalado → fabricado.
function migrate() { if (typeof migrateF7 === 'function') migrateF7(); /* FIX (fase 7) */ if (typeof migrateF7b === 'function') migrateF7b(); /* FIX (fase 7b) */ if (typeof migrateF8 === 'function') migrateF8(); /* FIX (fase 8) */ const c = state.crafted, it = state.items; if (c['Banot de viaje']) { delete c['Banot de viaje']; c['Garrote (palo de pastor)'] = 1; } delete c['Ungüento de mocán']; if (it.planta) { it.mocan = (it.mocan || 0) + it.planta; delete it.planta; } if (it.anzuelo) { delete it.anzuelo; c['Anzuelo de hueso'] = 1; } if (c['Gofio'] && !c['Fuego']) c['Fuego'] = 1; /* FIX (fase 4): partidas sin bolsillo ni decoraciones */ if (!state.decor || typeof state.decor !== 'object') state.decor = {}; cleanPocket(); migratePaint(); /* FIX (fase 5): símbolos y galería */ migrateF6(); /* FIX (fase 6) */ }
function resume() { migrate(); syncSoundBtn(); /* FIX (copia) */ if (!state.path) choosePath(); else if (!state.character) chooseCharacter(); else if (state.j1Done) map(); else journeyOneIntro(); }

const paths = [['risco', 'Camino del Risco', 'Supervivencia y ganadería', '+2 agilidad · +1 recolección', 'Rastrea, pastorea y cruza barrancos con seguridad.'], ['taller', 'Camino del Taller', 'Artesanía y economía', '+2 artesanía · +1 eficiencia', 'Convierte piedra, madera, piel y barro en soluciones útiles.'], ['almogaren', 'Camino del Almogarén', 'Sabiduría y ritos', '+2 sabiduría · +1 curación', 'Observa el cielo, cuida las plantas y protege la memoria.']];
function choosePath() {
  if (SCENES.camino.layout === 'stage') { go(`<div class="stage-wrap">${renderStage('camino')}</div>`, 'stage-screen'); return; }
  go(`<div class="panel panel-onart"><span class="eyebrow">PRIMERA DECISIÓN</span><h2>Elige tu camino</h2><p>Una especialización no define quién eres: define qué conocimiento quieres compartir con la comunidad.</p><div class="cards">${paths.map((p, i) => `<article class="path-card"><div class="art ${p[0]}" style="background-image:url('${SCENES.camino.arts[p[0]]}')" role="img" aria-label="Ilustración del ${p[1]}"></div><span class="tag">${p[2]}</span><h3>${p[1]}</h3><p>${p[4]}</p><b>${p[3]}</b><button class="parchment-btn choose" data-i="${i}">Elegir este camino</button></article>`).join('')}</div></div>`, 'camino-screen', 'camino');
  document.querySelectorAll('.choose').forEach(button => button.onclick = () => pickPath(Number(button.dataset.i)));
}
function pickPath(i) { state.path = { title: paths[i][1] }; state.pathId = paths[i][0]; chooseCharacter(); } // FIX: se guarda también el id del camino.

// FIX: textos neutros (R1): la pantalla dice que comparten capacidades y las descripciones ya no reparten «rastreador» y «recolectora» por género. Cada retrato recorta solo a su personaje (antes ambas tarjetas mostraban la imagen entera con los dos) y tiene alt.
function portrait(name) { if (SCENES.personajes.portraits) return `<div class="portrait portrait-new"><img src="${SCENES.personajes.portraits[name]}" alt="Retrato de ${name}"></div>`; /* FIX (final): retratos nuevos de cuerpo entero */ const crop = SCENES.personajes.crops[name]; return `<div class="portrait" role="img" aria-label="Retrato de ${name}" style="aspect-ratio:${crop.w * SCENES.personajes.ratio[0]}/${crop.h * SCENES.personajes.ratio[1]}"><img src="${SCENES.personajes.img}" alt="" style="width:${10000 / crop.w}%;left:${-crop.x * 100 / crop.w}%;top:${-crop.y * 100 / crop.h}%"></div>`; }
function chooseCharacter() {
  if (SCENES.personajes.layout === 'stage') { go(`<div class="stage-wrap">${renderStage('personajes')}</div>`, 'stage-screen'); return; }
  go(`<div class="character-layout"><h2>¿Quién caminará contigo?</h2><p class="on-image">Gaire y Tayda comparten capacidades. Elige la mirada con la que quieres aprender.</p><div class="character-cards"><article class="character-card">${portrait('Gaire')}<h3>Gaire</h3><p>Observa el terreno, cuida el rebaño y conoce las plantas.</p><button class="parchment-btn character" data-character="Gaire">Seleccionar a Gaire</button></article><article class="character-card">${portrait('Tayda')}<h3>Tayda</h3><p>Escucha la historia, cuida el rebaño y conoce las plantas.</p><button class="parchment-btn character" data-character="Tayda">Seleccionar a Tayda</button></article></div></div>`, 'character-screen', 'personajes');
  document.querySelectorAll('.character').forEach(button => button.onclick = () => pickCharacter(button.dataset.character));
}
function pickCharacter(name) { state.character = name; state.knowledge = 5; journeyOneIntro(); }

function journeyOneIntro() { state.j1Start = state.knowledge; go(`<div class="activity-card"><span class="eyebrow">JORNADA 1 · EL TERRITORIO HABLA</span><h2>La cabra que tomó otro sendero</h2><p>Al amanecer, Guayarmina descubre que una cabra se ha separado del rebaño. Antes de salir, Areguía te recuerda que una comunidad se orienta compartiendo lo que observa.</p><div class="dialogue with-npc"><span class="npc" style="background-image:url(\'img/npc_areguia.webp\')" aria-hidden="true"></span><b>Areguía</b><p>La isla no entrega sus respuestas a quien corre demasiado. Mira primero. Después decide.</p></div><p><b>Objetivo:</b> encuentra tres señales del paisaje y vuelve con la cabra sin dañar las plantas jóvenes.</p><button class="parchment-btn" id="startJ1">Seguir las huellas</button></div>`, 'activity-screen', 'j1Intro'); $('#startJ1').onclick = rastreo; }

function rastreo() {
  // FIX (final): la lámina nueva de pistas sigue el orden original del array (rama, piedra, ave, hierba, cabra, concha) y el barranco nuevo está limpio (sin indicios pintados): se recuperan las posiciones originales y cada pista usa su icono suelto.
  const clues = [
    ['Rama rota', 'Una rama fresca orientada hacia el barranco.', true, 17, 46, 'rama_rota'],
    ['Piedra desplazada', 'La piedra conserva tierra suelta en uno de sus lados.', true, 34, 58, 'piedra_desplazada'],
    ['Huella de ave', 'Una huella ligera: aporta información del entorno, pero no de la cabra.', false, 68, 58, 'huella_ave'],
    ['Hierba aplastada', 'La vegetación doblada junto al agua puede indicar un paso reciente.', true, 55, 73, 'hierba_aplastada'],
    ['Huella de cabra', 'Dos marcas de pezuña hendida en el suelo húmedo: la señal más directa.', true, 79, 76, 'huella_cabra'],
    ['Concha marina', 'Un resto costero fuera de lugar: interesante, pero no indica este rebaño.', false, 87, 42, 'concha_marina']
  ];
  // FIX: la escena va en un contenedor con la proporción real de la imagen, así los indicios no se desplazan al cambiar el tamaño de la ventana.
  const proofs = clues.map((clue, i) => `<button class="proof proof-${i}" data-proof="${i}" style="left:${clue[3]}%;top:${clue[4]}%" aria-label="${clue[0]}"><span class="proof-image" style="background-image:url('img/iconos/${clue[5]}.webp')"></span><span class="proof-tooltip"><b>${clue[0]}</b><small>${clue[1]}</small></span></button>`).join('');
  go(`<div class="trail-scene"><div class="stage-wrap trail-wrap">${renderStage('rastreo', `<div class="proof-layer" aria-label="Indicios del paisaje">${proofs}</div>`)}</div><div class="trail-copy"><span class="eyebrow">JORNADA 1 · RASTREO</span><h2>Leer las huellas</h2><p>Explora la escena. Toca o pulsa cada indicio para conocerlo y elige las tres señales que podrían indicar el paso de una cabra.</p><div class="trail-selection" id="trailSelection">0/3 señales seleccionadas</div></div><div class="trail-fact" id="trailFact">Selecciona un indicio para leer su ficha.</div><button class="parchment-btn next-btn trail-next" id="toChoice">Continuar</button></div>`, 'activity-screen trail-screen');
  const selected = new Set();
  document.querySelectorAll('.proof').forEach(button => button.onclick = () => { const i = Number(button.dataset.proof); if (selected.has(i)) { selected.delete(i); button.classList.remove('selected'); } else if (selected.size < 3) { selected.add(i); button.classList.add('selected'); } $('#trailSelection').textContent = `${selected.size}/3 señales seleccionadas`; $('#trailFact').innerHTML = `<b>${clues[i][0]}</b><br>${clues[i][1]} ${clues[i][2] ? 'Es un indicio útil para seguir el rastro.' : 'Es una pista del paisaje, pero no la que buscamos.'}`; $('#toChoice').classList.toggle('show', selected.size === 3); }); // FIX: si se deselecciona un indicio, el botón Continuar vuelve a ocultarse.
  $('#toChoice').onclick = () => {
    const wrong = [...selected].filter(index => !clues[index][2]); const good = wrong.length === 0;
    state.knowledge += good ? 8 : 3; state.confidence += 1; state.journal.push('rastreo', 'territorio');
    addItem('piel'); // FIX: antes state.items.piel = 1 sobrescribía la cantidad en vez de sumar.
    // FIX: si se eligió algún indicio falso, se explica cuál y por qué antes de seguir (antes se avanzaba sin ninguna explicación).
    if (!good) openModal(`<h2>Revisa tus pistas</h2><p>Has seguido el rastro, pero no todas tus señales hablaban de la cabra:</p>${wrong.map(index => `<p><b>${clues[index][0]}:</b> ${clues[index][1]}</p>`).join('')}<p>La huella de pezuña hendida es la señal más directa del paso de una cabra.</p>`);
    territoryChoice();
  };
}

function territoryChoice() { go(`<div class="activity-card"><span class="eyebrow">JORNADA 1 · DECISIÓN</span><h2>Una cabra, tres prioridades</h2><p>La encuentras junto a un grupo de plantas jóvenes. ¿Cómo actuarás?</p><div class="answers"><button class="answer decision" data-good="true">Proteger las plantas y guiarla después</button><button class="answer decision" data-good="false">Correr detrás de ella y arrancar las plantas para despejar el paso</button><button class="answer decision" data-good="true">Pedir ayuda y buscar un rodeo seguro</button></div><div class="fact" id="choiceFact"></div><button class="parchment-btn next-btn" id="toJump">Ir al barranco</button></div>`, 'activity-screen', 'j1Decision'); document.querySelectorAll('.decision').forEach(button => button.onclick = () => { document.querySelectorAll('.decision').forEach(b => b.disabled = true); const good = button.dataset.good === 'true'; button.classList.add(good ? 'correct' : 'wrong'); state.confidence += good ? 2 : 0; $('#choiceFact').textContent = good ? 'Cuidar una especie y mantener el rebaño forman parte del mismo problema: la supervivencia depende del equilibrio del entorno.' : 'La velocidad no resuelve el problema si destruye el recurso que hará falta mañana. Prueba a pensar en la comunidad y en el paisaje.'; $('#choiceFact').classList.add('show'); $('#toJump').classList.add('show'); }); $('#toJump').onclick = pastorJump; }

function pastorJump() { go(`<div class="activity-card"><span class="eyebrow">JORNADA 1 · SALTO DEL PASTOR</span><h2>Encontrar el apoyo</h2><p>Guayarmina te enseña el ritmo con su garrote (palo de pastor): mirar, apoyar, descender. Pulsa las marcas en orden para cruzar el pequeño barranco.</p><div class="jump-sequence"><button class="jump" data-step="0">1<br><small>Mirar</small></button><button class="jump" data-step="1">2<br><small>Apoyar</small></button><button class="jump" data-step="2">3<br><small>Descender</small></button></div><div class="fact" id="jumpFact"></div><p class="safety-note">Hoy se aprende con monitores. No lo intentes por tu cuenta.</p><button class="parchment-btn next-btn" id="finishJ1">Completar jornada</button></div>`, 'activity-screen', 'j1Salto'); let step = 0; document.querySelectorAll('.jump').forEach(button => button.onclick = () => { if (step === 3) return; /* FIX: tras completar la secuencia ya no se puede volver a sumar */ if (Number(button.dataset.step) !== step) { toast('Observa el orden: primero mira el terreno.'); return; } button.classList.add('correct'); step += 1; if (step === 3) { state.knowledge += 12; state.confidence += 1; state.day = 2; state.j1Done = true; state.journal.push('salto'); $('#jumpFact').textContent = 'El salto del pastor es una técnica tradicional viva para desplazarse por terrenos abruptos con un palo largo: en Gran Canaria, el garrote. La forma de practicarla puede variar según la isla y el lugar.'; $('#jumpFact').classList.add('show'); $('#finishJ1').classList.add('show'); setHUD(); } }); $('#finishJ1').onclick = completeJourneyOne; }

// FIX: la recompensa mostrada se calcula con lo ganado de verdad (antes ponía «+20 saber» fijo).
function completeJourneyOne() { const gained = state.knowledge - state.j1Start; go(`<div class="activity-card"><span class="eyebrow">JORNADA 1 COMPLETADA</span><h2>El camino queda abierto</h2><p>La cabra vuelve al rebaño y las plantas permanecen intactas. Has aprendido que el territorio también es una fuente histórica: guarda huellas, decisiones y formas de vivir.</p><div class="dialogue with-npc"><span class="npc" style="background-image:url(\'img/npc_guayarmina.webp\')" aria-hidden="true"></span><b>Guayarmina</b><p>Hoy no has corrido más que nadie. Has mirado mejor. Eso también es una forma de avanzar.</p></div><div class="reward-row"><span>✦ +${gained} saber</span><span>◒ Piel de cabra</span><span>▣ 3 fichas</span></div><button class="parchment-btn" id="returnMap">Abrir mapa</button></div>`, 'activity-screen', 'j1Intro'); $('#returnMap').onclick = map; }

// FIX: mapa en un contenedor con la proporción real (896×1195), sin estirar; las etiquetas son capas HTML siempre visibles colocadas sobre las pintadas, con un pulso sutil; el título HTML va en el panel lateral para no tapar el pintado.
// FIX (final): el mapa nuevo no trae texto; el título y la «Sala de patrimonio» son capas HTML de SCENES.mapa. El panel lateral resume la jornada y da acceso al silbo (J2.3) y al final común.
function allDone() { return ['playa', 'bosque', 'templo'].every(id => state.done[id]) && state.crafted['Gofio']; }
// FIX (móvil): lista alternativa de lugares (botones grandes) que se muestra en pantallas pequeñas debajo o al lado del mapa; usa las mismas acciones que los lugares de la ilustración.
function mapList() { const places = SCENES.mapa.layers.filter(layer => layer.action && layer.action.startsWith('hotspot:')); return `<nav class="map-list" aria-label="Lugares del mapa"><span class="eyebrow">LUGARES DEL MAPA</span><div class="map-list-grid">${places.map(layer => `<button class="map-place" data-action="${layer.action}" data-place="${layer.action.split(':')[1]}">${layer.text}</button>`).join('')}</div></nav>`; }
function map() { const pending = ['playa', 'bosque', 'templo'].filter(id => !state.done[id]).length; go(`<div class="map-layout"><aside class="map-side"><span class="eyebrow">JORNADA ${state.day} · ISLA DE GRAN CANARIA</span>${SCENES.mapa.baked ? '<h2>Mapa principal</h2>' : `<h2>Jornada ${state.day}</h2>`}<p>Pulsa los lugares señalados en la ilustración para continuar.</p><p class="map-progress">${pending ? `Retos de saber pendientes: ${pending} de 3` : 'Has completado los tres retos de saber.'}</p><p class="map-progress">${state.crafted['Gofio'] ? '✓ Gofio preparado' : 'Encargo: preparar gofio (cebada + molino de mano + fuego)'}</p><button class="parchment-btn side-btn" id="riscoBtn">${state.done.salto2 && state.done.datiles ? '✓ ' : '⛰ '}${state.pathId === 'risco' ? 'Retos del Camino del Risco' : 'Reto opcional · el risco'}</button><button class="parchment-btn side-btn fire-btn" id="hogueraBtn">🔥 La hoguera · historias de la noche</button><button class="parchment-btn side-btn" id="silboBtn">${state.done.silbo ? '✓ ' : ''}Ecos de La Gomera · silbo</button>${allDone() ? '<button class="parchment-btn side-btn final-btn" id="finalBtn">✦ La noche compartida</button>' : ''}</aside><div class="stage-wrap map-wrap">${renderStage('mapa')}</div>${mapList()}</div>`, 'map-screen'); document.querySelectorAll('.stage-mapa [data-action], .map-list [data-action]').forEach(button => { const id = button.dataset.action.split(':')[1]; if (state.done[id]) button.classList.add('done'); }); $('#silboBtn').onclick = goSilbo; $('#riscoBtn').onclick = riscoHub; $('#hogueraBtn').onclick = () => { const nn = nightState(); nn.nights = (typeof nn.nights === 'number' ? nn.nights : 0) + 1; save(); hoguera(); }; /* FIX (fase 7b): cuenta las noches para «una luna cada noche» */ if ($('#finalBtn')) $('#finalBtn').onclick = finale; }
// FIX (final): el minijuego de silbo es una página propia (silbo/index.html) que comparte fuentes, estilo y guardado mediante silbo/puente.js.
function goSilbo() { save(); location.href = 'silbo/index.html'; }
// FIX (final): final común del guion («La noche compartida»), con la variación del camino y la frase de confianza alta.
function finale() { const variation = { risco: 'Un sendero seguro guía al pueblo: la lectura del terreno permite desplazarse sin riesgo.', taller: 'Los objetos fabricados pasan de mano en mano sobre una mesa de herramientas compartidas.', almogaren: 'El cielo nocturno se mezcla con las siluetas de las montañas mientras la comunidad observa.' }[state.pathId] || ''; state.journal.push('relacion'); setHUD(); go(`<div class="activity-card"><span class="eyebrow">FINAL · LA NOCHE COMPARTIDA</span><h2>La noche compartida</h2><p>La comunidad se reúne junto al fuego. Abres la entrada final del Cuaderno: <b>Vivir es relacionarse</b>.</p><p>${variation}</p><div class="dialogue with-npc"><span class="npc" style="background-image:url(\'img/npc_areguia.webp\')" aria-hidden="true"></span><b>Areguía</b><p>Hoy no has traído respuestas para cerrar la historia. Has traído preguntas para que siga viva.</p></div>${state.confidence >= 4 ? '<div class="dialogue with-npc"><span class="npc" style="background-image:url(\'img/npc_guayarmina.webp\')" aria-hidden="true"></span><b>Guayarmina</b><p>Lo que aprendiste no se queda en tu zurrón. Ya forma parte del pueblo.</p></div>' : ''}<div class="reward-row"><span>✦ ${state.knowledge} saber</span><span>▣ ${new Set(state.journal).size} fichas</span></div><button class="parchment-btn" id="finalMap">Volver al mapa</button></div>`, 'activity-screen final-screen', 'final'); $('#finalMap').onclick = map; }
// FIX: la sala de patrimonio muestra la carta del Ídolo con cartelas HTML en español que tapan el texto pintado erróneo; sus botones pintados ahora funcionan.
function heritage() { openModal(`<h2>La memoria en los objetos</h2><div class="heritage-grid">${renderStage('idolo')}<div>${npcDialogue('Idaira', 'Mira la postura, el material y las marcas. Antes de preguntar qué significa, pregunta qué podemos observar realmente.')}<div class="fact" id="idoloLupa"><b>Observa con la lupa:</b> una figura de barro cocido sentada, de piernas gruesas, con decoración incisa. Lo que vemos es material y forma; para qué se usaba no se sabe con seguridad.</div><div class="fact" id="idoloMas"><b>Saber más:</b> la pieza original se conserva en El Museo Canario y no tiene datación directa. Esta ilustración es una <b>recreación</b>: no reproduce con exactitud la pieza del museo.</div><p><b>Ídolo de Tara:</b> figura de terracota asociada a Gran Canaria. Su postura sentada y sus rasgos materiales son observables; su función exacta debe tratarse con prudencia.</p><figure class="heritage-fig"><img src="img/pintaderas_mesa.webp" alt="Pintaderas de barro sobre una mesa de estudio, junto a una regla y un cuaderno"><figcaption>Pintaderas: observa antes de interpretar.</figcaption></figure><p><b>Pintaderas:</b> piezas de barro con diseños geométricos. Pueden relacionarse con identidad, decoración o señalización, pero no conviene afirmar un único significado.</p><div class="heritage-actions"><button class="parchment-btn" id="verPintaderas">Vitrina de pintaderas</button><button class="parchment-btn" id="verCeramica">Vitrina de cerámica pintada</button></div></div></div>`, 'wide'); $('#verPintaderas').onclick = () => discoverSymbols('pt'); $('#verCeramica').onclick = () => discoverSymbols('ce'); } // FIX (fase 5): aquí se descubren símbolos

// FIX: cada lugar del mapa abre su función (antes «Recolectar» abría la Playa, «Almacén» abría el zurrón y Pueblo y Taller hacían lo mismo).
function hotspot(id) { if (id === 'taller') craft(); else if (id === 'pueblo') village(); else if (id === 'casa') house(); else if (id === 'recolectar') monte(); /* FIX (fase 6): escena explorable del monte */ else if (id === 'rebaño') visit('rebaño'); else if (id === 'playa') playaHub(); /* FIX (fase 4): marisqueo + reto de saber */ else if (id === 'bosque' || id === 'templo') activity(id); else if (id === 'almacen') storehouse(); else if (id === 'zurron') inventory(); else if (id === 'cantera') quarry(); else if (id === 'campos') fields(); else if (id === 'patrimonio') heritage(); }
function village() { openModal(`<h2>El pueblo</h2><p>Talleres, bancales y vida comunitaria. Aquí se comparte lo que cada persona aprende en el territorio.</p><div class="fact show village-fact"><b>¿Quién decidía?</b> Según las crónicas, Gran Canaria tenía dos guanartemes (Gáldar y Telde). El faycán dirigía los ritos y los guaires eran nobles del consejo que aconsejaba al guanarteme. <button class="link-btn" id="fichaGobierno">Leer la ficha</button></div><p>Encargos de esta jornada: ${['playa', 'bosque', 'templo'].map(id => `${state.done[id] ? '✓' : '○'} ${locations[id].name}`).join(' · ')}</p><button class="parchment-btn" data-action="hotspot:taller">Ir a los talleres (3 estaciones)</button>`); state.journal.push('gobierno'); setHUD(); $('#fichaGobierno').onclick = () => showFicha('gobierno'); } // FIX (fase 3): guanarteme, faycán y guaire, con fuente
function house() { openModal(`<h2>La casa y la comunidad</h2><p>La vivienda no es solo un refugio: organiza la vida cotidiana, el almacenamiento, el descanso y las relaciones entre personas. En el juego, la casa permite revisar el estado del viaje y conversar con la comunidad.</p><div class="reward-row light"><span>✦ ${state.knowledge} saber</span><span>☼ Jornada ${state.day}/5</span><span>▣ ${new Set(state.journal).size} fichas</span></div><p class="save-note">La partida se guarda sola en este navegador. No se guarda ningún dato personal.</p><button class="parchment-btn" id="resetGame">Empezar de nuevo</button>`); $('#resetGame').onclick = () => { if (!confirm('¿Borrar la partida guardada y volver a empezar?')) return; clearSave(); resetState(); closeModal(); intro(); }; }
// FIX: nueva zona de recogida: madera, piedra, támara y junco se obtienen aquí una sola vez (antes algunas recetas eran imposibles).
// FIX (fase 6): el antiguo modal gather()/gatherables se sustituye por la escena explorable monte() (más abajo). Los recursos de todo el año siguen usando state.gathered, así que las partidas antiguas conservan lo ya recogido.
// FIX: el almacén es la reserva comunitaria (antes abría el zurrón); presta una vasija de barro una vez, necesaria para el ungüento ahora que el Templo no entrega objetos.
// FIX: la cebada se obtiene aquí, en la cueva-granero: el cereal cosechado se guardaba en graneros colectivos y es lo más fiel a cómo se conseguía a diario (una vez por partida).
// FIX (final): con el mapa nuevo, que pinta los bancales y ARTE.md los rotula «Campos de cebada», la cebada se siega en los campos; el almacén queda como reserva (vasija).
// FIX (fase 6) C: el antiguo modal fields() (segar 1 cebada) se sustituye por el ciclo agrícola completo fields() (más abajo); la cebada rápida para el gofio pasa al Almacén como «reserva del año pasado».
function storehouse() { const row = (key, title, text, btn, done) => `<div class="recipe"><div><b>${title}</b><small>${text}</small></div><button class="parchment-btn store" data-key="${key}" ${state.gathered[key] ? 'disabled' : ''}>${state.gathered[key] ? done : btn}</button></div>`; openModal(`<img class="modal-banner" src="img/j4_almacen.webp" alt="Risco de toba con cámaras-granero y personas subiendo cestas"><h2>Almacén comunitario</h2><p>La cueva-granero guarda la reserva del pueblo: cereal, vasijas y herramientas que se comparten.</p>${row('cebada', 'Cebada de la reserva', 'Del grano guardado el año pasado: para tostar y moler el gofio.', 'Tomar', '✓ Tomada')}${granaryRow()}${row('ceramica', 'Vasija de barro', 'Préstamo de la reserva para preparar un remedio.', 'Pedir prestada', '✓ Prestada')}${row('ceramica2', 'Otra vasija de barro', 'Para decorarla con almagre en la estación de pigmentos.', 'Pedir prestada', '✓ Prestada')}`); document.querySelectorAll('.store').forEach(button => button.onclick = () => { const key = button.dataset.key; if (state.gathered[key]) return; state.gathered[key] = true; addItem(key === 'ceramica2' ? 'ceramica' : key); /* FIX (fase 4): segunda vasija */ button.disabled = true; button.textContent = key === 'cebada' ? '✓ Tomada' : '✓ Prestada'; }); if ($('#granFicha')) $('#granFicha').onclick = () => showFicha('granero'); /* FIX (fase 6) C */ }
// FIX: cantera: el jugador tiene que ELEGIR la piedra adecuada para el molino (porosa, que «muerde» el grano). Solo la correcta entra al zurrón (×2: una por muela), una vez por partida.
function quarry() { const stones = [['lisa', 'Canto rodado liso', 'Duro y pulido por el mar: sin poros, no agarra el grano al moler.'], ['porosa', 'Piedra volcánica llena de pequeños huecos', 'Basalto con poros o toba: su superficie áspera tritura el grano. Es la que se usaba para los molinos.'], ['obsidiana', 'Obsidiana (vidrio volcánico)', 'Muy cortante: servía para hacer filos, no para moler.']]; openModal(`<h2>La cantera</h2><p>En esta ladera volcánica se sacaban bloques de piedra para hacer molinos de mano. ¿Qué piedra elegirías para moler grano?</p>${state.gathered.volcanica ? '<p class="done-note-dark">✓ Ya extrajiste los dos bloques para tu molino.</p>' : ''}<div class="answers light-answers">${stones.map(([id, name]) => `<button class="answer stone" data-id="${id}" ${state.gathered.volcanica ? 'disabled' : ''}>${name}</button>`).join('')}</div><p id="stoneFact" class="stone-fact" aria-live="polite"></p>${veins()}`); document.querySelectorAll('.stone').forEach(button => button.onclick = () => { const stone = stones.find(st => st[0] === button.dataset.id); $('#stoneFact').textContent = stone[2]; if (stone[0] !== 'porosa') { button.classList.add('wrong'); return; } button.classList.add('correct'); document.querySelectorAll('.stone').forEach(b => b.disabled = true); state.gathered.volcanica = true; addItem('volcanica'); addItem('volcanica', true); toast('Has extraído 2 bloques de piedra volcánica porosa · llévalos al taller'); }); bindVeins(); }

// FIX (fase 3): REBAÑO tras la jornada 1: hueso y cuerno (se aprovechaba todo el animal), manteca de leche de cabra y los retos del Camino del Risco.
function herd() { const row = (key, title, text) => `<div class="recipe-card"><img class="ricon" src="img/iconos/${key}.webp" alt=""><div class="rbody"><b>${title}</b><small>${text}</small></div><div class="recipe-actions"><button class="parchment-btn herd" data-key="${key}" ${state.gathered[key] ? 'disabled' : ''}>${state.gathered[key] ? '✓ Recibido' : 'Pedir'}</button></div></div>`; openModal(`<img class="modal-banner" src="img/j1_salto_pastor.webp" alt="Pastoras y cabras en una ladera"><h2>El rebaño</h2>${npcDialogue('Guayarmina', 'De la cabra se aprovecha todo: carne, leche, piel, hueso y cuerno. Y el risco se baja con calma.')}<div class="craft-list">${row('hueso', 'Hueso y cuerno de cabra', 'Restos que quedaron tras el consumo de carne: sirven para hacer anzuelos y puntas.')}${row('manteca', 'Manteca de cabra', 'Se hacía con leche de cabra y se guardaba en vasijas.')}${row('leche', 'Leche de cabra ×2', 'Recién ordeñada: para amasar el gofio y cocer el frangollo.')}${row('carne', 'Carne', 'De un animal sacrificado para todo el pueblo: se reparte.')}</div><button class="parchment-btn" id="toRisco">${state.pathId === 'risco' ? '⛰ Retos del Camino del Risco' : '⛰ Reto opcional del risco'}</button> <button class="parchment-btn" id="toTrack">🐾 Rastreo de animales</button>`); /* FIX (fase 6) B: acceso al rastreo */ document.querySelectorAll('.herd').forEach(button => button.onclick = () => { const key = button.dataset.key; if (state.gathered[key]) return; state.gathered[key] = true; addItem(key); if (key === 'leche') addItem(key, true); /* FIX (fase 6) D: dos cuencos */ button.disabled = true; button.textContent = '✓ Recibido'; }); $('#toRisco').onclick = riscoHub; $('#toTrack').onclick = () => { closeModal(); trackHub(); }; }
function visit(id) { if (!state.visited.includes(id)) state.visited.push(id); if (id === 'pueblo') craft(); else if (id === 'rebaño' && !state.journal.includes('rastreo')) journeyOneIntro(); else if (id === 'rebaño') herd(); /* FIX (fase 3): el rebaño da hueso y manteca y abre los retos del risco */ else activity(id); }
// FIX: el objeto se entrega solo con el primer acierto (antes al entrar, sin responder), el saber se suma una vez por reto y la jornada ya no avanza con cada pregunta. El Templo no entrega objetos (R4): desbloquea la ficha «Cómo sabemos lo que sabemos».
// FIX (final): diálogos con retrato de Fayna (conocedora de plantas) e Idaira (guardiana del almogarén); textos del guion (J2.1, J3.2, J5 y patrimonio).
function npcDialogue(name, text) { return `<div class="dialogue with-npc"><span class="npc npc-${name.toLowerCase()}" style="background-image:url('img/npc_${name.toLowerCase()}.webp')" aria-hidden="true"></span><b>${name}</b><p>${text}</p></div>`; }
const npcLines = { bosque: ['Fayna', 'Una planta no es solo su nombre. También es el suelo donde crece, la estación, la parte que se utiliza y la forma de prepararla.'], playa: ['Fayna', 'Hay relatos sobre el uso de savias vegetales para aturdir peces en charcos. Lo estudiaremos como conocimiento histórico, sin convertirlo en una instrucción para practicar hoy.'], templo: ['Idaira', 'Orientarse no es dibujar cualquier figura en el cielo. Es recordar una relación entre tiempo, lugar y horizonte.'] };
function activity(id) { const data = { playa: ['El embarbascado', '¿Qué se hacía en algunos charcos para aturdir temporalmente a los peces?', ['Se empleaba savia vegetal en una zona pequeña', 'Se encendía una hoguera dentro del agua', 'Se usaban redes de nylon'], 'El embarbascado debe tratarse como práctica histórica y con contexto. El juego no propone reproducirlo hoy. Recoges lapas del charco. ¿Y viajar entre islas? No hay pruebas de barcos aborígenes: es un tema de debate (nueva ficha).'], bosque: ['Etnobotánica', '¿Qué idea es más rigurosa al estudiar una planta?', ['Relacionar planta, parte usada, preparación y contexto', 'Suponer que toda planta sirve como medicina', 'Arrancar varios ejemplares para comprobarlo'], 'El conocimiento vegetal depende del entorno y de la preparación. Un uso tradicional no equivale automáticamente a una recomendación actual.'], templo: ['Puzle de constelaciones', '¿Qué observación ayuda a orientarse sin convertir una hipótesis en certeza?', ['Relacionar estrellas, horizonte y puntos del paisaje', 'Afirmar que toda alineación es un observatorio', 'Seguir solo la luz de una hoguera'], 'La relación entre cielo y paisaje puede estudiarse, pero las interpretaciones sobre prácticas astronómicas deben presentarse como hipótesis cuando la evidencia es limitada. El almogarén era un lugar de culto y reunión: los difuntos no se depositaban aquí, sino en cuevas y túmulos (nueva ficha).'] }[id]; const loot = { playa: 'lapas', bosque: 'mocan' }[id]; /* FIX (fase 3): el anzuelo ya no se regala: se fabrica en el taller */ const done = !!state.done[id]; go(`<div class="activity-card"><span class="eyebrow">${locations[id].name.toUpperCase()} · RETO DE SABER</span><h2>${data[0]}</h2><p>${locations[id].desc}. Responde y descubre un dato histórico.</p>${npcLines[id] ? npcDialogue(...npcLines[id]) : ''}${done ? '<p class="done-note">✓ Ya completaste este reto. Puedes repasarlo, pero no suma más saber.</p>' : ''}<div class="question">${data[1]}</div><div class="answers">${data[2].map((answer, i) => `<button class="answer quiz" data-answer="${i}">${answer}</button>`).join('')}</div><div class="fact" id="quizFact">${data[3]}</div><button class="parchment-btn next-btn" id="backMap">Volver al mapa</button>${id === 'bosque' ? '<button class="parchment-btn next-btn silbo-next" id="toSilbo">Oír un silbo a distancia ›</button>' : ''}${id === 'templo' ? '<div class="balos-box"><p>Idaira: «Los antiguos canarios también grababan signos en la roca, como en el barranco de Balos (Agüimes)».</p><button class="parchment-btn" id="verBalos">Grabados de Balos</button></div><div class="balos-box"><p>Idaira: «En los años secos se pedía la lluvia, y hay quien piensa que en Risco Caído la luz marcaba el calendario».</p><button class="parchment-btn" id="verLluvia">Ritos de lluvia y calendario</button></div>' : ''}</div>`, 'activity-screen', id); if ($('#verBalos')) $('#verBalos').onclick = () => discoverSymbols('gc'); /* FIX (fase 5) */ if ($('#verLluvia')) $('#verLluvia').onclick = rainRites; /* FIX (fase 6) C */ document.querySelectorAll('.quiz').forEach(button => button.onclick = () => { if ($('#quizFact').classList.contains('show')) return; const ok = button.dataset.answer === '0'; button.classList.add(ok ? 'correct' : 'wrong'); if (ok) { $('#quizFact').classList.add('show'); $('#backMap').classList.add('show'); if ($('#toSilbo')) $('#toSilbo').classList.add('show'); if (!state.done[id]) { state.done[id] = true; state.knowledge += 10; if (loot) addItem(loot); if (id === 'templo') state.journal.push('fuentes', 'enterramiento'); if (id === 'playa') state.journal.push('islas'); setHUD(); toast(id === 'bosque' ? '¡Conocimiento adquirido! +10 saber' : '¡Conocimiento adquirido! +10 saber · nueva ficha en el Cuaderno'); } } else toast('Lee la pregunta otra vez y observa el contexto.'); }); $('#backMap').onclick = map; if ($('#toSilbo')) $('#toSilbo').onclick = goSilbo; /* FIX (final): guion J2.3: tras el bosque, el silbo a distancia */ }

function addItem(id, quiet = false) { state.items[id] = (state.items[id] || 0) + 1; state.knowledge += 2; setHUD(); if (!quiet) toast(`Has guardado ${resources.find(item => item[0] === id)[1]} · +2 saber`); }
// FIX: lo fabricado entra en el zurrón (state.crafted), cada receta se fabrica y puntúa una sola vez y el botón sigue desactivado al volver al taller.
