//  · mode: 'polish' (mantener pulsado / golpes, como el molino) · 'steps' (pasos en orden) · tools: herramientas que NO se gastan.
const stations = [
  { id: 'madera', name: 'Madera y piedra', icon: 'img/iconos/garrote.webp', scene: 'estMadera', who: 'Nauzet', line: 'Una herramienta no empieza cuando golpeamos. Empieza cuando elegimos qué piedra sirve, qué madera resiste y cuánto material podemos gastar.' },
  { id: 'secado', name: 'Secado y curtido', icon: 'img/iconos/cuero.webp', scene: 'estSecado', who: 'Nauzet', line: 'El sol, el tiempo y las manos: la piel, el junco y la palma se secan antes de transformarse.' },
  { id: 'cocina', name: 'Fuego y cocina', icon: 'img/iconos/fuego.webp', scene: 'estCocina', who: 'Fayna', line: 'Lo que comemos sale del campo, del ganado, del mar y del monte. Y de los remedios antiguos aprendemos, pero no los repetimos sin pensar.' }, // FIX (fase 6) D: cocina unificada (antes «Medicinas y comida»)
  { id: 'pigmentos', name: 'Pigmentos', icon: 'img/iconos/pigmento_rojo.webp', scene: 'estPigmentos', who: 'Idaira', line: 'Antes de preguntar qué significa un dibujo, mira de qué está hecho: tierra, agua, fuego y manos.' } // FIX (fase 4): cuarta estación
];
