  const tick = now => { const dt = Math.min(0.05, (now - last) / 1000); last = now; if (!busy) { pos += dir * speed() * dt; if (pos > 100) { pos = 100; dir = -1; } if (pos < 0) { pos = 0; dir = 1; } cursor.style.left = `${pos}%`; stage.dataset.inzone = pos >= zoneStart && pos <= zoneStart + zoneW ? '1' : '0'; } if (document.body.contains(stage)) raf = requestAnimationFrame(tick); };
