// Cinemática corta y saltable: tres ilustraciones (sin texto) con subtítulos en capa HTML. Con movimiento reducido no hay zoom y se avanza a mano.
function cinematic(done) {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const frames = [['img/risco/cine_1.webp', 'La cabra escapa risco abajo.'], ['img/risco/cine_2.webp', 'El salto: el garrote encuentra el apoyo.'], ['img/risco/cine_3.webp', 'El descenso: la cabra vuelve con el rebaño.']];
  const el = document.createElement('div'); el.className = `cine${reduce ? ' cine-still' : ''}`; el.setAttribute('role', 'dialog'); el.setAttribute('aria-label', 'Cinemática del salto del pastor');
  el.innerHTML = `${frames.map(([src, text], n) => `<figure class="cine-frame${n === 0 ? ' on' : ''}"><img src="${src}" alt="${text}"><figcaption>${text}</figcaption></figure>`).join('')}<div class="cine-bar"><button class="parchment-btn" id="cineNext">Siguiente ›</button><button class="parchment-btn secondary-btn" id="cineSkip">Saltar cinemática</button></div>`;
  document.body.append(el); let n = 0, timer = 0; const end = () => { clearTimeout(timer); el.remove(); done(); };
  const show = k => { n = k; if (n >= frames.length) { end(); return; } el.querySelectorAll('.cine-frame').forEach((f, i) => f.classList.toggle('on', i === n)); $('#cineNext').textContent = n === frames.length - 1 ? 'Continuar ›' : 'Siguiente ›'; clearTimeout(timer); if (!reduce) timer = setTimeout(() => show(n + 1), 3200); };
  $('#cineNext').onclick = () => show(n + 1); $('#cineSkip').onclick = end; el.addEventListener('keydown', event => { if (event.key === 'Escape') end(); }); show(0); $('#cineSkip').focus();
}

// PIEDRAS Y TÁMARAS: arrastra desde la honda (tirachinas) hacia atrás para apuntar (ángulo) y tensar (fuerza), o ajusta los deslizadores y pulsa «Lanzar». Hay que bajar 3 racimos con 8 piedras.
function datilesGame() {
  const bunches = [[70, 37], [73.6, 41], [77.2, 38], [80.8, 41], [84.4, 37]];
  go(`<div class="mini-wrap"><div class="mini-head"><span class="eyebrow">CAMINO DEL RISCO · PIEDRAS Y TÁMARAS</span><h2>Bajar támaras de la palmera</h2><p>Arrastra hacia atrás desde la piedra para apuntar y tensar, y suelta para lanzar. También puedes usar los deslizadores. Baja <b>3 racimos</b> con 8 piedras.</p></div><div class="mini-stage datiles-stage" id="datStage" style="background-image:url('img/risco/palmera_fondo.webp')">${bunches.map(([x, y], n) => `<img class="bunch" data-b="${n}" src="img/iconos/datiles.webp" alt="Racimo de támaras" style="left:${x}%;top:${y}%">`).join('')}<img class="spr pastor thrower" src="img/risco/pastor.webp" alt=""><span class="stone-ball" id="stoneBall"></span><svg class="aim" id="aim" viewBox="0 0 100 56.25" preserveAspectRatio="none" aria-hidden="true"><polyline id="aimLine" points="" /></svg><span class="sling" id="sling" aria-hidden="true"></span></div><div class="mini-controls throw-controls"><label>Ángulo <input type="range" id="ang" min="15" max="80" value="52"><output id="angOut">52°</output></label><label>Fuerza <input type="range" id="pow" min="20" max="100" value="62"><output id="powOut">62 %</output></label><button class="parchment-btn big-btn" id="lanzar">Lanzar piedra</button><span class="mini-info" id="datInfo" aria-live="polite">Piedras: 8 · Racimos: 0/3</span></div><p class="safety-note">Recreación histórica: hoy no se tiran piedras a las palmeras ni a las personas.</p></div>`, 'activity-screen mini-screen', 'risco');
  const stage = $('#datStage'), ball = $('#stoneBall'), ang = $('#ang'), pow = $('#pow'), aimLine = $('#aimLine');
  const O = [13.5, 74]; let stones = 8, hits = 0, flying = false, drag = null;
  const physics = () => { const r = stage.getBoundingClientRect(); return { W: r.width, H: r.height, g: 1.5 * r.width, vmax: 1.9 * r.width }; };
  const vel = () => { const { vmax } = physics(); const a = Number(ang.value) * Math.PI / 180, v = vmax * (0.3 + 0.7 * Number(pow.value) / 100); return [v * Math.cos(a), -v * Math.sin(a)]; };
  const sync = () => { $('#angOut').textContent = `${ang.value}°`; $('#powOut').textContent = `${pow.value} %`; preview(); };
  const preview = () => { const { W, H, g } = physics(); if (!W || !H) return; /* escena aún sin medir o ya cerrada */ const [vx, vy] = vel(); const pts = []; for (let t = 0; t < 0.55; t += 0.05) { const x = O[0] / 100 * W + vx * t, y = O[1] / 100 * H + vy * t + g * t * t / 2; pts.push(`${(x / W * 100).toFixed(2)},${(y / H * 56.25).toFixed(2)}`); } aimLine.setAttribute('points', pts.join(' ')); };
  const info = () => { $('#datInfo').textContent = `Piedras: ${stones} · Racimos: ${hits}/3`; };
  const throwStone = () => { if (flying || stones <= 0 || hits >= 3) return; flying = true; stones -= 1; info(); const { W, H, g } = physics(); let [vx, vy] = vel(); let x = O[0] / 100 * W, y = O[1] / 100 * H, last = performance.now(); ball.classList.add('on');
    const step = now => { const dt = Math.min(0.03, (now - last) / 1000); last = now; vy += g * dt; x += vx * dt; y += vy * dt; ball.style.left = `${x / W * 100}%`; ball.style.top = `${y / H * 100}%`;
      const hit = [...document.querySelectorAll('.bunch:not(.down)')].find(b => { const bx = parseFloat(b.style.left) / 100 * W, by = parseFloat(b.style.top) / 100 * H; return Math.hypot(bx - x, by - y) < W * 0.04; });
      if (hit) { hit.classList.add('down'); hits += 1; addItem('tamara', true); info(); toast(`¡Racimo abajo! +1 támara (${hits}/3)`); }
      if (hit || x > W * 1.05 || y > H * 1.02 || x < -W * 0.05) { ball.classList.remove('on'); flying = false; if (!hit) toast('Casi: cambia el ángulo o la fuerza.'); if (hits >= 3) setTimeout(datilesWin, 500); else if (stones <= 0) setTimeout(datilesRetry, 500); return; }
      requestAnimationFrame(step); };
    requestAnimationFrame(step); };
  // Arrastre tipo honda: el vector desde el punto de inicio hasta el dedo, invertido, da el ángulo; su longitud, la fuerza.
  stage.addEventListener('pointerdown', event => { if (flying) return; event.preventDefault(); try { stage.setPointerCapture(event.pointerId); } catch (error) { /* sin captura */ } drag = { x: event.clientX, y: event.clientY, moved: false }; });
  stage.addEventListener('pointermove', event => { if (!drag) return; const dx = drag.x - event.clientX, dy = event.clientY - drag.y; if (Math.hypot(dx, dy) < 12) return; drag.moved = true; const { W } = physics(); ang.value = Math.round(Math.max(15, Math.min(80, Math.atan2(dy, Math.max(1, dx)) * 180 / Math.PI))); pow.value = Math.round(Math.max(20, Math.min(100, Math.hypot(dx, dy) / (W * 0.25) * 100))); sync(); });
  const release = () => { if (!drag) return; drag = null; throwStone(); }; // arrastrar y soltar lanza; un toque corto lanza con los valores actuales
  stage.addEventListener('pointerup', release); stage.addEventListener('pointercancel', () => { drag = null; }); stage.addEventListener('contextmenu', event => event.preventDefault());
  let extra = false; pocketHandler = key => { if (key !== 'piedra') { toast(`${pocketItem(key).name}: aquí no se usa.`); return; } if (extra) { toast('Ya usaste las piedras de tu bolsillo.'); return; } extra = true; stones += 2; info(); toast('+2 piedras de tu bolsillo'); }; /* FIX (fase 4): bolsillo */ ang.oninput = sync; pow.oninput = sync; $('#lanzar').onclick = throwStone; window.addEventListener('resize', preview, { once: true }); sync();
}
function datilesRetry() { openModal('<h2>Se acabaron las piedras</h2><p>Recoge otras ocho piedras del cauce y vuelve a intentarlo. Observa la trayectoria punteada: un poco más de ángulo hace la curva más alta.</p><button class="parchment-btn" id="datAgain">Intentarlo otra vez</button>'); $('#datAgain').onclick = () => { closeModal(); datilesGame(); }; }
function datilesWin() { const first = !state.done.datiles; if (first) { state.done.datiles = true; state.knowledge += 12; } state.journal.push('datiles'); setHUD(); go(`<div class="activity-card"><span class="eyebrow">CAMINO DEL RISCO · PIEDRAS Y TÁMARAS</span><h2>Támaras para compartir</h2><p>Has bajado tres racimos. Las támaras se reparten: un alimento dulce que se guardaba y se compartía.</p><div class="reward-row"><span>✦ ${first ? '+12 saber' : 'Reto repetido'}</span><span>● +3 támaras</span><span>▣ Ficha: támaras de la palmera canaria</span></div><div class="fact show">${fichas.datiles.text}</div><button class="parchment-btn" id="datFicha">Ver ficha con fuentes</button> <button class="parchment-btn" id="datMap">Volver al mapa</button></div>`, 'activity-screen', 'risco'); $('#datFicha').onclick = () => showFicha('datiles'); $('#datMap').onclick = map; }

let pocketHandler = null;
// FIX (fase 4): BOLSILLO · tres casillas de acceso rápido además del zurrón. Cada casilla guarda una clave: el id de un recurso («piedra») o «c:» + el nombre de un objeto fabricado.
// Los objetos del bolsillo se usan tocándolos en el marcador: cada pantalla (estación, marisqueo, decorar, dátiles) define pocketHandler. go() lo reinicia.
function pocketItem(key) { if (!key || typeof key !== 'string') return null; if (key.startsWith('c:')) { const name = key.slice(2); return state.crafted[name] ? { key, name, icon: craftedIcons[name] || 'img/iconos/molino.webp', count: 0, crafted: true } : null; } const res = resources.find(r => r[0] === key); return res && state.items[key] > 0 ? { key, name: res[1], icon: res[3], count: state.items[key], crafted: false } : null; }
function cleanPocket() { if (!Array.isArray(state.pocket)) state.pocket = [null, null, null]; state.pocket = [0, 1, 2].map(i => (pocketItem(state.pocket[i]) ? state.pocket[i] : null)); state.pocket.forEach((key, i) => { if (key && state.pocket.indexOf(key) !== i) state.pocket[i] = null; }); }
function inPocket(key) { return Array.isArray(state.pocket) && state.pocket.includes(key); }
function slotHTML(key, i, cls) { const it = pocketItem(key); return `<button class="${cls}${it ? ' full' : ''}" data-slot="${i}" aria-label="${it ? `Bolsillo ${i + 1}: ${it.name}${it.count ? ` (${it.count})` : ''}` : `Bolsillo ${i + 1}: vacío`}">${it ? `<img src="${it.icon}" alt="" draggable="false">${it.count > 1 ? `<b>${it.count}</b>` : ''}` : '<span aria-hidden="true">+</span>'}</button>`; }
function renderPocket() { const box = $('#pocket'); if (!box) return; cleanPocket(); box.querySelector('.pocket-slots').innerHTML = state.pocket.map((key, i) => slotHTML(key, i, 'pocket-slot')).join(''); box.querySelectorAll('.pocket-slot').forEach(button => button.onclick = () => { const key = state.pocket[Number(button.dataset.slot)]; if (key && pocketHandler && $('#modal').classList.contains('hidden')) pocketHandler(key); else inventory(); }); }
function putInPocket(key) { cleanPocket(); if (inPocket(key)) return; let slot = state.pocket.indexOf(null); if (slot < 0) slot = 2; state.pocket[slot] = key; setHUD(); toast(`${pocketItem(key).name}: al bolsillo ${slot + 1}`); }

// FIX (fase 4): MARISQUEO · charcos de marea en la costa de basalto. Solo se recogen lapas y burgados (las especies que dominan los concheros); la carnadilla y el cangrejo se observan.
function playaHub() { openModal(`<img class="modal-banner" src="img/playa/charcos_fondo.webp" alt="Charcos de marea entre rocas de basalto, con algas verdes, pardas y rojas"><h2>Playa del Marisqueo</h2>${npcDialogue('Nauzet', 'El mar deja cosas y también se lleva cosas. Mira la marea: cuando sube, los charcos se cierran.')}<div class="craft-list"><div class="recipe-card"><img class="ricon" src="img/playa/lapa_arriba.webp" alt=""><div class="rbody"><b>Marisqueo en los charcos</b><small>Lapas y burgados con la marea baja. Lleva en el bolsillo una piedra para despegar las lapas.</small></div><div class="recipe-actions"><button class="parchment-btn" id="goMar">${state.done.marisqueo ? '✓ Repetir' : 'Jugar'}</button></div></div><div class="recipe-card"><img class="ricon" src="img/iconos/vieja.webp" alt=""><div class="rbody"><b>El embarbascado</b><small>Reto de saber sobre los charcos y los peces.</small></div><div class="recipe-actions"><button class="parchment-btn" id="goQuiz">${state.done.playa ? '✓ Repasar' : 'Responder'}</button></div></div></div>`); $('#goMar').onclick = () => { closeModal(); marisqueoPrep(); }; $('#goQuiz').onclick = () => { closeModal(); activity('playa'); }; }
function marisqueoPrep() {
  cleanPocket(); const row = (key, icon, title, text, have) => `<div class="recipe-card${inPocket(key) ? ' made' : ''}"><img class="ricon" src="${icon}" alt=""><div class="rbody"><b>${title}</b><small>${text}</small></div><div class="recipe-actions">${inPocket(key) ? '<span class="chip ok">✓ En el bolsillo</span>' : have ? `<button class="parchment-btn to-pocket" data-key="${key}">Al bolsillo</button>` : '<span class="chip miss">No lo tienes</span>'}</div></div>`;
  go(`<div class="activity-card"><span class="eyebrow">PLAYA · MARISQUEO</span><h2>Prepara el bolsillo</h2><p>Baja con las manos libres: lo que lleves en el bolsillo se usa directamente en los charcos. La marea baja dura poco.</p>${row('piedra', 'img/iconos/canto.webp', 'Piedra basáltica', 'Para despegar las lapas con un golpe seco. Si no llevas, Nauzet te presta un canto.', state.items.piedra > 0)}${row('c:Bolsa de junco', 'img/iconos/bolsa.webp', 'Bolsa de junco', 'Con ella caben 10 piezas en vez de 6.', !!state.crafted['Bolsa de junco'])}${row('c:Anzuelo de hueso', 'img/iconos/anzuelo.webp', 'Anzuelo de hueso', 'Al terminar podrás pescar con un burgado como cebo.', !!state.crafted['Anzuelo de hueso'])}<button class="parchment-btn big-btn" id="toCharcos">Bajar a los charcos ›</button> <button class="parchment-btn secondary-btn" id="marBack">Volver al mapa</button></div>`, 'activity-screen', 'playa');
  document.querySelectorAll('.to-pocket').forEach(button => button.onclick = () => { putInPocket(button.dataset.key); marisqueoPrep(); });
  pocketHandler = () => toast('Ya está en el bolsillo: lo usarás en los charcos.');
  $('#toCharcos').onclick = marisqueoGame; $('#marBack').onclick = map;
}
function marisqueoGame() {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches; const T = reduce ? 110 : 75, TOP = 22;
  let tool = inPocket('piedra'), cap = inPocket('c:Bolsa de junco') ? 10 : 6, basket = 0, left = 0, fails = 0, over = false; const got = { lapa: 0, burgado: 0 }, seen = {};
  const list = [['lapa', 8, 52], ['lapa', 17, 80], ['lapa', 89, 61], ['lapa', 70, 88], ['lapa', 46, 29], ['lapa', 93, 41], ['lapa', 27, 91, 1], ['lapa', 82, 79, 1], ['burgado', 12, 66], ['burgado', 58, 88], ['burgado', 86, 49], ['burgado', 31, 31], ['burgado', 41, 93, 1], ['burgado', 96, 73, 1], ['carnadilla', 5, 38], ['carnadilla', 76, 35], ['cangrejo', 21, 46], ['cangrejo', 90, 89]].map(([t, x, y, small]) => ({ t, x, y, small: !!small, obs: t === 'carnadilla' || t === 'cangrejo', relaxed: false, next: 0 }));
  const label = o => o.t === 'lapa' ? (o.small ? 'Lapa pequeña' : 'Lapa') : o.t === 'burgado' ? (o.small ? 'Burgado pequeño' : 'Burgado') : o.t === 'carnadilla' ? 'Carnadilla (observar)' : 'Cangrejo moro (observar)';
  go(`<div class="mini-wrap"><div class="mini-head"><span class="eyebrow">PLAYA · MARISQUEO EN LOS CHARCOS</span><h2>Antes de que suba la marea</h2><p>Las lapas se agarran a la roca: espera a que la concha <b>se levante un poco</b> (brilla) y tócala para despegarla de un golpe seco. Los burgados se cogen a mano. <b>Deja las pequeñas.</b></p></div><div class="mini-stage mar-stage" id="marStage" style="background-image:url('img/playa/charcos_fondo.webp')">${list.map((o, i) => `<button class="shell sh-${o.t}${o.small ? ' small' : ''}${o.obs ? ' obs' : ''}" data-i="${i}" style="left:${o.x}%;top:${o.y}%" aria-label="${label(o)}"><img src="img/playa/${o.t === 'lapa' ? 'lapa_arriba' : o.t}.webp" alt="" draggable="false"></button>`).join('')}<div class="tide" id="tide" style="top:${TOP}%"></div></div><div class="mini-controls"><div class="tide-clock" aria-hidden="true"><span>Marea</span><i><b id="tideFill"></b></i></div><span class="mini-info" id="marInfo" aria-live="polite"></span><button class="parchment-btn big-btn" id="marEnd">Volver a la orilla</button></div><p class="safety-note" id="marMsg" aria-live="polite">${tool ? 'Llevas la piedra en el bolsillo.' : 'Nauzet te presta un canto rodado (pon una piedra en el bolsillo para usar la tuya).'}</p></div>`, 'activity-screen mini-screen', 'marisqueo');
  const stage = $('#marStage'), tide = $('#tide'), els = [...stage.querySelectorAll('.shell')];
  const say = text => { $('#marMsg').textContent = text; };
  const info = () => { $('#marInfo').textContent = `Lapas ${got.lapa} · Burgados ${got.burgado} · Cesta ${basket}/${cap}`; };
  const end = () => { if (over) return; over = true; setTimeout(() => marisqueoEnd({ lapa: got.lapa, burgado: got.burgado, left, fails, seen, tool }), 500); };
  const hit = i => { const o = list[i], el = els[i]; if (over || o.taken || o.covered) return;
    if (o.t === 'carnadilla') { seen.carnadilla = true; el.classList.add('seen'); say('Carnadilla: aparece en los concheros aborígenes, pero hoy su marisqueo está sometido a veda en Canarias. La miramos y la dejamos.'); return; }
    if (o.t === 'cangrejo') { seen.cangrejo = true; el.classList.add('seen'); say('Cangrejo moro: corre entre las rocas. En los concheros no aparecen sus restos, así que no sabemos si se comía. Lo dejamos.'); return; }
    if (o.small) { if (!el.classList.contains('left')) left += 1; el.classList.add('left'); say(`${o.t === 'lapa' ? 'Lapa pequeña' : 'Burgado pequeño'}: lo dejamos crecer para que pueda reproducirse.`); return; }
    if (basket >= cap) { say(`La cesta está llena (${cap}).${cap < 10 ? ' Con la bolsa de junco en el bolsillo caben 10.' : ''} Vuelve a la orilla.`); return; }
    if (o.t === 'lapa' && !o.relaxed) { fails += 1; o.next = performance.now() + 1300; el.classList.remove('clamp'); void el.offsetWidth; el.classList.add('clamp'); say('¡Se ha agarrado! Al notar el golpe, la lapa se pega a la roca. Espera a que la concha se levante.'); return; }
    o.taken = true; el.classList.add('taken'); basket += 1; got[o.t] += 1; info(); say(o.t === 'lapa' ? `Lapa despegada con ${tool ? 'tu piedra' : 'el canto prestado'}.` : 'Burgado recogido a mano.');
    if (basket >= cap || list.every(p => p.taken || p.small || p.obs || p.covered)) end(); };
  els.forEach((el, i) => { el.addEventListener('pointerdown', event => { event.preventDefault(); hit(i); }); el.addEventListener('click', event => { if (event.detail === 0) hit(i); }); el.addEventListener('contextmenu', event => event.preventDefault()); });
  pocketHandler = key => { if (key === 'piedra') { tool = true; say('Usas la piedra de tu bolsillo para despegar las lapas.'); } else if (key === 'c:Bolsa de junco') { cap = 10; info(); say('Bolsa de junco a mano: ahora caben 10 piezas.'); } else if (key === 'c:Anzuelo de hueso') say('El anzuelo lo usarás al terminar, para pescar con un burgado como cebo.'); else say(`${pocketItem(key).name}: no sirve para mariscar.`); };
  const t0 = performance.now();
  const loop = now => { if (over || !document.body.contains(stage)) return; const f = Math.min(1, (now - t0) / 1000 / T), line = TOP + f * (100 - TOP); tide.style.height = `${f * (100 - TOP)}%`; $('#tideFill').style.width = `${(1 - f) * 100}%`;
    list.forEach((o, i) => { if (!o.covered && !o.taken && o.y < line) { o.covered = true; els[i].classList.add('covered'); els[i].disabled = true; } if (o.t === 'lapa' && !o.taken && !o.small && now > o.next) { o.relaxed = !o.relaxed; o.next = now + (o.relaxed ? (reduce ? 1900 : 1150) : 1200 + Math.random() * 1400); els[i].classList.toggle('relaxed', o.relaxed); } });
    if (f >= 1) { say('La marea ha cubierto los charcos.'); end(); return; } requestAnimationFrame(loop); };
  list.forEach((o, i) => { o.next = t0 + 300 + i * 170; }); info(); requestAnimationFrame(loop);
  $('#marEnd').onclick = end;
}
function marisqueoEnd(r) {
  const first = !state.done.marisqueo; for (let n = 0; n < r.lapa; n++) addItem('lapas', true); for (let n = 0; n < r.burgado; n++) addItem('burgado', true);
  if (first && r.lapa + r.burgado > 0) { state.done.marisqueo = true; state.knowledge += 12; state.confidence += r.left ? 1 : 0; }
  state.journal.push('marisqueo', 'lapas', 'burgado', 'sostenibilidad'); if (r.seen.carnadilla) state.journal.push('carnadilla'); if (r.seen.cangrejo) state.journal.push('cangrejo'); setHUD();
  const canFish = inPocket('c:Anzuelo de hueso') && state.items.burgado > 0; const total = r.lapa + r.burgado;
  go(`<div class="activity-card"><span class="eyebrow">PLAYA · MARISQUEO</span><h2>${total ? 'La cesta vuelve a la orilla' : 'Esta vez ganó la marea'}</h2><p>Lapas: <b>${r.lapa}</b> · Burgados: <b>${r.burgado}</b>${r.left ? ` · Has dejado crecer <b>${r.left}</b> ${r.left > 1 ? 'ejemplares pequeños' : 'ejemplar pequeño'}` : ''}.${r.fails ? ` Algunas lapas se agarraron (${r.fails}): el golpe tiene que pillarlas desprevenidas.` : ''}</p><div class="reward-row"><span>✦ ${first && total ? '+12 saber' : total ? 'Reto repetido' : 'Sin saber extra'}</span><span>▣ Fichas: concheros · lapas · burgados · cuidar el marisco</span></div><div class="fact show sustain"><b>Hoy, en Canarias</b> (normativa actual, no aborigen): las lapas deben medir al menos 45 mm y los burgados 15 mm; del 1 de diciembre al 30 de abril no se pueden coger, y hay zonas vedadas todo el año. No sabemos qué normas tenían los antiguos canarios: estas son las de hoy, para que el marisco siga existiendo.</div>${canFish ? '<button class="parchment-btn" id="goPesca">Pescar con el anzuelo (cebo: un burgado) ›</button> ' : `<p class="station-note">${state.crafted['Anzuelo de hueso'] ? 'Para pescar, lleva el anzuelo de hueso en el bolsillo y guarda un burgado como cebo.' : 'Si fabricas el anzuelo de hueso en el taller, podrás pescar al terminar.'}</p>`}<button class="parchment-btn" id="marFicha">Ver fichas con fuentes</button> <button class="parchment-btn" id="marMap">Volver al mapa</button></div>`, 'activity-screen', 'playa');
  $('#marFicha').onclick = () => openModal(`<h2>Fichas del marisqueo</h2>${['marisqueo', 'lapas', 'burgado', 'sostenibilidad', 'carnadilla', 'cangrejo'].map(fichaHTML).join('')}`, 'wide'); $('#marMap').onclick = map; if ($('#goPesca')) $('#goPesca').onclick = pescaGame;
}
// PESCA en la orilla: el anzuelo de hueso del bolsillo y un burgado como cebo. Se tira del sedal cuando el agua salpica (picada).
function pescaGame() {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches; let biting = false, done = false, timer = 0, early = 0;
  go(`<div class="mini-wrap"><div class="mini-head"><span class="eyebrow">PLAYA · PESCA CON ANZUELO</span><h2>Esperar la picada</h2><p>El anzuelo de hueso lleva un burgado de cebo. Cuando el agua <b>salpique</b> sobre el anzuelo, tira del sedal. Si tiras antes, el pez se asusta.</p></div><div class="mini-stage pesca-stage" id="pescaStage" style="background-image:url('img/playa/charcos_fondo.webp')"><svg class="sedal" viewBox="0 0 100 56.25" preserveAspectRatio="none" aria-hidden="true"><path id="sedalLine" d="M8 56 Q30 20 50 12" /></svg><span class="ripple" id="ripple"></span><img class="vieja-spr" id="viejaSpr" src="img/iconos/vieja.webp" alt="Vieja"></div><div class="mini-controls"><button class="parchment-btn big-btn" id="tirar">Tirar del sedal</button><span class="mini-info" id="pescaInfo" aria-live="polite">Esperando…</span></div><p class="safety-note">La vieja es uno de los peces más frecuentes en los yacimientos aborígenes de Gran Canaria.</p></div>`, 'activity-screen mini-screen', 'marisqueo');
  const stage = $('#pescaStage'); const wait = () => { biting = false; stage.classList.remove('bite'); clearTimeout(timer); timer = setTimeout(() => { if (!document.body.contains(stage)) return; biting = true; stage.classList.add('bite'); $('#pescaInfo').textContent = '¡Pica!'; timer = setTimeout(() => { if (!done) { $('#pescaInfo').textContent = 'Se escapó. Espera otra picada.'; wait(); } }, reduce ? 2200 : 1300); }, 1400 + Math.random() * 1800); };
  const pull = () => { if (done) return; if (!biting) { early += 1; $('#pescaInfo').textContent = 'Demasiado pronto: el pez se asusta. Espera a que salpique.'; wait(); return; } done = true; clearTimeout(timer); stage.classList.remove('bite'); stage.classList.add('caught'); state.items.burgado = Math.max(0, (state.items.burgado || 0) - 1); addItem('vieja', true); const first = !state.done.pesca; if (first) { state.done.pesca = true; state.knowledge += 8; } state.journal.push('pesca'); setHUD(); $('#pescaInfo').textContent = '¡Una vieja!'; setTimeout(() => { go(`<div class="activity-card"><span class="eyebrow">PLAYA · PESCA CON ANZUELO</span><h2>Una vieja para la comunidad</h2><p>Has gastado un burgado como cebo${early ? ` y has tirado antes de tiempo ${early} ${early > 1 ? 'veces' : 'vez'}` : ''}. La vieja se puede asar en la estación de medicinas y comida.</p><div class="reward-row"><span>✦ ${first ? '+8 saber' : 'Reto repetido'}</span><span>≻ +1 vieja</span><span>▣ Ficha: pescar en la orilla</span></div><div class="fact show">${fichas.pesca.text}</div><button class="parchment-btn" id="pescaFicha">Ver ficha con fuentes</button> <button class="parchment-btn" id="pescaMap">Volver al mapa</button></div>`, 'activity-screen', 'playa'); $('#pescaFicha').onclick = () => showFicha('pesca'); $('#pescaMap').onclick = map; }, reduce ? 200 : 900); };
  const button = $('#tirar'); button.addEventListener('pointerdown', event => { event.preventDefault(); pull(); }); button.addEventListener('click', event => { if (event.detail === 0) pull(); }); button.addEventListener('contextmenu', event => event.preventDefault()); wait();
}

// FIX (fase 4): PIGMENTOS · decorar con los colores preparados. Las figuras se generan en el juego (SVG): inspiradas en la Cueva Pintada y la cerámica de Gran Canaria, sin copiar ninguna pintura.
// FIX (fase 5): JUEGO DE PINTADO en tres pasos (elegir símbolos → preparar colorantes → componer en una vasija o en una pared de toba).
// Sustituye al panel, la vasija y el cuero de la fase 4. Los símbolos se redibujan en SVG por el propio juego (no son fotos) y cada uno lleva su procedencia y su fuente.
const PIG = { 'Rojo de almagre': ['rojo', '#9b3220', 'Rojo almagre'], 'Blanco de tierra clara': ['blanco', '#efe5cf', 'Blanco'], 'Negro de hollín': ['negro', '#231d19', 'Negro de hollín'] };
const PAINT = Object.fromEntries(Object.values(PIG).map(([id, hex]) => [id, hex]));
const GALLERY_KEY = 'vida-aborigen-galeria-v1'; // la galería va aparte de la partida: solo guarda los dibujos (sin nombres ni fechas)
const SYM_START = ['cp_roleo', 'cp_cuadro4', 'ce_triangulos'];
const SYM_GROUPS = {
  cp: { name: 'Cueva Pintada de Gáldar', place: 'Pigmentos · «Mirar la cámara pintada»', ficha: 'panel', intro: 'La cámara de la Cueva Pintada (Gáldar) se pintó a partir del siglo XII con almagre y arcillas blancas sobre la toba, en paneles a media altura. El zócalo de abajo quedó sin pintar.', src: ['cpGuia', 'cpTrazado', 'cpZephyrus'] },
  pt: { name: 'Pintaderas de Gran Canaria', place: 'Sala de patrimonio · vitrina de pintaderas', ficha: 'pintaderas', intro: 'Las pintaderas son sellos de barro cocido. Sus dibujos están grabados (incisos, excisos o impresos) en la base: no están pintados.', src: ['pintaderasMC', 'gevic', 'pintaderasEst'] },
  ce: { name: 'Cerámica pintada de Gran Canaria', place: 'Sala de patrimonio · vitrina de cerámica', ficha: 'vasijaPintada', intro: 'La cerámica aborigen de Gran Canaria se bruñía y se pintaba, sobre todo con almagre, en bandas y frisos. En las otras islas se decoraba sobre todo con incisiones.', src: ['cpGuia', 'cerera', 'ceramicaFuneraria'] },
  gc: { name: 'Grabados de Balos (Gran Canaria)', place: 'Almogarén · «Grabados de Balos»', ficha: 'grabadosBalos', intro: 'En el Lomo de los Letreros (barranco de Balos, Agüimes) hay 49 paneles grabados en el basalto. Son Bien de Interés Cultural: se miran, no se tocan.', src: ['bocBalos', 'balosULPGC'] },
  lp: { name: 'Grabados de La Palma', place: 'Cuaderno · «Otras islas»', ficha: 'grabadosLaPalma', intro: 'Otra isla, otra tradición: en La Palma hay cientos de estaciones con grabados picados en la roca. Los primeros se describieron en la cueva de Belmaco (1752).', src: ['emartinLP', 'belmaco', 'belmacoDibujo'] }
};
const stroke = (c, w = 2) => `fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"`;
const spiral = () => { const p = []; for (let t = 0; t <= 6 * Math.PI; t += 0.25) { const r = 0.6 + t * 0.47; p.push(`${(r * Math.cos(t)).toFixed(2)},${(r * Math.sin(t)).toFixed(2)}`); } return p.join(' '); };
const checker = (n, size, c) => { let s = ''; const cell = size / n, o = -size / 2; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if ((i + j) % 2 === 0) s += `<rect x="${(o + i * cell).toFixed(2)}" y="${(o + j * cell).toFixed(2)}" width="${cell.toFixed(2)}" height="${cell.toFixed(2)}" fill="${c}"/>`; return s; };
// [id, grupo, nombre, dónde (isla · yacimiento u objeto), técnica original, nota, dibujo]
