Object.assign(fichas, {
  hoguera: { title: 'Contar para recordar', label: 'Idea del juego', text: 'Mucho de lo que sabemos de los antiguos canarios llegó porque alguien lo contó y un cronista lo escribió, a veces un siglo después. Cada vez que una historia se cuenta, cambia un poco. Por eso, junto a la hoguera, el juego separa lo que es dato (las fichas, con su fuente) de lo que es relato (tu historia y sus adornos).' },
  lunas: { title: 'Contar el tiempo por lunas', label: 'Crónicas (versiones distintas)', text: 'Abreu Galindo escribe que en Gran Canaria no distinguían los días del año ni los meses «más que con las lunas». Marín de Cubas (s. XVII) añade que el año, llamado «acano», empezaba con la primera luna nueva después del 21 de junio, y que, recogida la cosecha, hacían nueve días de bailes, banquetes y bodas; también habla de rayas hechas en tablas, paredes o piedras para llevar la cuenta. Torriani (finales del s. XVI) escribe que el rey de Gran Canaria contaba el tiempo por «520 esplendores de la luna», es decir, por lunas llenas. Otra crónica (Sedeño) dice que el año empezaba en primavera, pero también sitúa la cosecha y las fiestas «por fines de junio»; algunos autores creen que hablaba de Tenerife. Las fuentes coinciden en junio para la fiesta y no en dónde empieza la cuenta: el juego muestra las dos versiones.', source: [SRC.abreu, SRC.jimenezMUNA] },
  pleyades: { title: 'El grupito de estrellas (Pléyades)', label: 'Dato astronómico + hipótesis de otra isla', text: 'Hoy llamamos Pléyades a este grupito de estrellas apretadas (es un nombre griego). Entre los años 1000 y 1500, en Canarias, reaparecían antes del amanecer a finales de mayo. Un cronista cuenta que en Lanzarote y Fuerteventura veían a los espíritus de los antepasados «en forma de nubecitas» al amanecer del día más largo del año; unos investigadores proponen que esas nubecitas eran las Pléyades, las Híades y la Vía Láctea. Es una hipótesis y es de otras islas: para Gran Canaria no hay ningún dato.', source: [SRC.barrios2019, SRC.tindaya, SRC.jimenezMUNA] },
  cinturon: { title: 'Tres estrellas en fila', label: 'Astronomía actual · sin nombre aborigen', text: 'Las tres estrellas en fila son el «cinturón de Orión», un nombre de la mitología griega. No sabemos qué nombre les daban los antiguos canarios, y el juego no se lo inventa. Sirven para orientarse: siguiendo la fila hacia abajo se llega a Sirio.' },
  sirio: { title: 'Sirio, la más brillante', label: 'Dato astronómico · sin dato aborigen en Gran Canaria', text: 'Sirio es la estrella más brillante del cielo nocturno. En Canarias, entre los años 1000 y 1500, reaparecía antes del amanecer a mediados de julio. Ninguna crónica de Gran Canaria la menciona. Para Fuerteventura, un investigador interpreta a dos mujeres sabias de un relato (Tamonante y Tibiabin) como Venus y Sirio: es solo una interpretación.', source: [SRC.barrios2019, SRC.jimenezMUNA] },
  canopo: { title: 'Canopo, la estrella del sur', label: 'Dato astronómico + hipótesis discutida', text: 'Canopo es la segunda estrella más brillante. Desde Gran Canaria se ve muy baja sobre el horizonte sur (como mucho unos 9 grados) y desde casi toda Europa no se ve nunca. Hacia el año 1500 dejaba de verse a mediados de abril y reaparecía a mediados de agosto. El investigador José Barrios propone que su reaparición se celebraba en varias islas (en Tenerife, el mes de la cosecha, «beñesmer», era agosto) y que fiestas actuales como la del Pino de Teror podrían venir de ese culto. Es una hipótesis discutida, no un hecho comprobado.', source: [SRC.barrios2019, SRC.jimenezMUNA] },
  c_olvido: { title: 'Nos pusieron aquí y nos olvidaron', label: 'Relato recogido por un cronista · Gran Canaria', text: 'Andrés Bernáldez, cronista de finales del siglo XV, cuenta que preguntaron a los canarios más ancianos de dónde venían. Respondieron que sus antepasados les dijeron que Dios los puso y dejó allí y se olvidó de ellos, y que por algún lugar se les abriría «un ojo o luz». Es una frase muy breve y pasada por la mirada cristiana del cronista. Que esa luz sea el sol es una interpretación de investigadores actuales.', source: [SRC.jimenezMUNA] },
  c_atidamana: { title: 'Atidamana y Gumidafe', label: 'Crónica · entre historia y leyenda', text: 'Abreu Galindo (h. 1600) cuenta que en Gáldar vivía una joven, Atidamana, cuyas palabras ponían paz en las peleas. Con el tiempo dejaron de escucharla por ser mujer; entonces se casó con Gumidafe, un capitán que vivía en unas cuevas junto a Gáldar, y juntos sometieron a los demás capitanes y gobernaron toda la isla. Según el cronista, su hijo Artemis reinó después, y dos hijos de este se repartieron después la isla en Gáldar y Telde. Se escribió más de un siglo después de los hechos y los nombres cambian según el cronista (Atidamana, Andamana).', source: [SRC.abreu, SRC.rhc] },
  c_tibicenas: { title: 'Los tibicenas', label: 'Creencia recogida por un cronista · Gran Canaria', text: 'Abreu Galindo escribe que a los canarios se les aparecían, de noche y a veces de día, unos seres «como grandes perros lanudos» y con otras figuras, a los que llamaban «tibisenas». El cronista, que era fraile, los explica como apariciones del demonio: es su interpretación cristiana, no necesariamente la de los canarios. Muchas historias modernas sobre tibicenas añaden detalles que no están en la crónica.', source: [SRC.abreu] },
  c_tierra: { title: 'Gente de tierra y agua', label: 'Otra isla: Tenerife · crónica', text: 'Según Abreu Galindo, en Tenerife decían que Dios los había hecho de tierra y agua, tantos hombres como mujeres, y les dio ganado; después creó más gente y no le dio ganado, y cuando la pidieron les dijo que sirvieran a los primeros y ellos les darían de comer. Así explicaban por qué unos tenían rebaños y otros servían. No es un relato de Gran Canaria.', source: [SRC.abreuIII] },
  c_gara: { title: 'Gara y Jonay', label: 'Leyenda moderna · La Gomera (s. XIX)', text: 'Es la leyenda de amor más conocida de Canarias, pero no es un relato aborigen. Lo más probable es que naciera en el siglo XIX, con la moda de las historias románticas; la versión escrita más antigua conocida es de 1924. Los nombres «Gara» y «Jonay» se sacaron del nombre de la montaña, Garajonay, que ya existía; no al revés. Además, los antiguos canarios no navegaban entre islas.', source: [SRC.garaWiki, SRC.garaToponimo, SRC.garaMDC, SRC.genoma] }
});
// ---- Registro de la hoguera ----
const HEARTH = [];
function registerHearth(def) { const i = HEARTH.findIndex(h => h.id === def.id); if (i >= 0) HEARTH[i] = def; else HEARTH.push(def); return def; }
const NPC_IMG = { Areguía: 'areguia', Fayna: 'fayna', Idaira: 'idaira', Nauzet: 'nauzet', Guayarmina: 'guayarmina' };
function fireVoice(name, text) { return `<div class="dialogue with-npc fire-voice"><span class="npc npc-${NPC_IMG[name]}" style="background-image:url('img/npc_${NPC_IMG[name]}.webp')" aria-hidden="true"></span><b>${name}</b><p>${text}</p></div>`; }
function nightState() { if (!state.night || typeof state.night !== 'object') state.night = {}; const n = state.night; if (!Array.isArray(n.told)) n.told = []; if (!n.heard || typeof n.heard !== 'object') n.heard = {}; if (!n.sky || typeof n.sky !== 'object') n.sky = {}; if (typeof n.stories !== 'number') n.stories = n.told.length; return n; }
function migrateF7() { nightState(); }
