const OPENINGS = ['Las llamas crujen y todos se acercan. Respiras hondo y empiezas:', 'Areguía echa una rama al fuego y te mira: «Te toca». Empiezas despacio:', 'Las estrellas ya han salido. Con la voz baja, para que hasta los pequeños escuchen, cuentas:'];
