// ---- ASTRONOMÍA 1: mirar el cielo (esquema simplificado, cielo de invierno mirando al sur) ----
const SKY = { pleyades: [1400, 95], aldebaran: [1270, 165], betelgeuse: [945, 85], bellatrix: [1095, 105], belt1: [1065, 170], belt2: [1012, 196], belt3: [960, 222], saiph: [955, 330], rigel: [1100, 318], sirio: [745, 345], canopo: [705, 590] };
const SKY_STEPS = [
  { id: 'pleyades', ask: 'Busca un grupito de estrellas pequeñas muy juntas, arriba a la derecha.', hint: 'Parece una mancha brillante, como una nubecita.', targets: ['pleyades'], ficha: 'pleyades', name: 'Pléyades' },
  { id: 'cinturon', ask: 'Ahora busca tres estrellas en fila, en el centro del cielo. Tócalas una a una.', hint: 'Están muy juntas, en diagonal, en medio de un gran rectángulo de estrellas.', targets: ['belt1', 'belt2', 'belt3'], ficha: 'cinturon', name: 'Cinturón de Orión' },
  { id: 'sirio', ask: 'Sigue la fila de tres hacia abajo y a la izquierda: llegarás a la estrella más brillante.', hint: 'Prolonga la diagonal del cinturón hacia la izquierda.', targets: ['sirio'], ficha: 'sirio', name: 'Sirio' },
  { id: 'canopo', ask: 'Muy baja, casi rozando las montañas del sur, hay una estrella que desde Europa casi nunca se ve. Encuéntrala.', hint: 'Mira justo encima de las crestas, debajo de Sirio.', targets: ['canopo'], ficha: 'canopo', name: 'Canopo' }
];
function skyStarsSVG() { let r = 7; const rnd = () => (r = (r * 9301 + 49297) % 233280) / 233280; const bg = Array.from({ length: 150 }, () => { const x = rnd() * 1600, y = rnd() * 480 + (rnd() < .2 ? 60 : 0); return `<circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="${(rnd() * 1.8 + .6).toFixed(1)}" fill="#fff" opacity="${(rnd() * .5 + .25).toFixed(2)}"/>`; }).join('');
  const star = (id, size, color = '#fff') => { const [x, y] = SKY[id]; return `<g class="sky-star" data-star="${id}"><circle cx="${x}" cy="${y}" r="${size * 3.2}" fill="url(#glow)" opacity=".7"/><circle cx="${x}" cy="${y}" r="${size}" fill="${color}"/></g>`; };
  const ple = [[0, 0], [22, -10], [-18, 8], [10, 18], [32, 10], [-6, -20], [40, -14]].map(([dx, dy], i) => `<circle cx="${SKY.pleyades[0] + dx}" cy="${SKY.pleyades[1] + dy}" r="${i < 4 ? 4 : 3}" fill="#dfe8ff"/>`).join('');
  return `<svg class="sky-svg" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Cielo nocturno de invierno sobre las cumbres de Gran Canaria"><defs><radialGradient id="glow"><stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#9fb8ff" stop-opacity="0"/></radialGradient></defs><g class="bg-stars">${bg}</g><g id="skyLines"></g><g class="sky-star" data-star="pleyades"><circle cx="${SKY.pleyades[0] + 12}" cy="${SKY.pleyades[1]}" r="60" fill="url(#glow)" opacity=".35"/>${ple}</g>${star('aldebaran', 6, '#ffcf9a')}${star('betelgeuse', 7, '#ffb07a')}${star('bellatrix', 5)}${star('belt1', 5.5)}${star('belt2', 5.5)}${star('belt3', 5.5)}${star('saiph', 5)}${star('rigel', 7, '#cfe0ff')}${star('sirio', 10, '#eaf2ff')}${star('canopo', 7, '#fff1d6')}<g id="skyLabels"></g>${Object.keys(SKY).map(id => `<circle class="sky-hit" data-star="${id}" cx="${SKY[id][0] + (id === 'pleyades' ? 12 : 0)}" cy="${SKY[id][1]}" r="${id === 'pleyades' ? 60 : 34}" tabindex="0" role="button" aria-label="${id === 'pleyades' ? 'Grupito de estrellas' : 'Estrella'}"/>`).join('')}</svg>`; }
function skyGame() { const n = nightState(), sky = n.sky; let step = SKY_STEPS.findIndex(s => !sky[s.id]); if (step < 0) step = 0; let belt = []; const found = new Set(SKY_STEPS.filter(s => sky[s.id]).map(s => s.id));
  go(`<div class="mini-wrap sky-wrap"><div class="mini-head"><span class="eyebrow">LA NOCHE · ASTRONOMÍA</span><h2>Mirar el cielo</h2><p>Noche de invierno mirando al sur desde las cumbres. Esquema simplificado: las posiciones son aproximadas.</p></div><div class="mini-stage sky-stage" style="background-image:url('img/noche/cielo.webp')">${skyStarsSVG()}</div><div class="sky-info" id="skyInfo" aria-live="polite"></div><div class="mini-controls"><button class="parchment-btn" id="skyHint">Pista</button><button class="parchment-btn" id="skyWheel">◔ Rueda del año</button><button class="parchment-btn" id="skyBack">Volver a la hoguera</button></div><p class="safety-note">Los nombres de las estrellas son los de hoy. No conocemos los nombres que les daban los antiguos canarios, y el juego no se los inventa.</p></div>`, 'activity-screen mini-screen sky-screen', 'cielo');
  const svg = $('.sky-svg'), info = $('#skyInfo');
  const label = (id, text) => { const [x, y] = SKY[id === 'cinturon' ? 'belt1' : id]; $('#skyLabels').insertAdjacentHTML('beforeend', `<text x="${x + 22}" y="${y - 22}" class="sky-label">${text}</text>`); };
  const lines = () => { let l = ''; if (found.has('cinturon')) l += `<polyline points="${['belt1', 'belt2', 'belt3'].map(k => SKY[k].join(',')).join(' ')}" class="sky-line"/>`; if (found.has('sirio')) l += `<line x1="${SKY.belt3[0]}" y1="${SKY.belt3[1]}" x2="${SKY.sirio[0]}" y2="${SKY.sirio[1]}" class="sky-line dashed"/>`; $('#skyLines').innerHTML = l; };
  SKY_STEPS.forEach(s => { if (found.has(s.id)) { label(s.id, s.name); s.targets.forEach(t => svg.querySelector(`.sky-star[data-star="${t}"]`).classList.add('found')); } }); lines();
  const show = (msg = '') => { if (step >= SKY_STEPS.length) { info.innerHTML = `<h3>¡Cielo completo!</h3><p>Has encontrado las Pléyades, el cinturón de Orión, Sirio y Canopo. Ahora mira cuándo aparece y desaparece cada una en la rueda del año.</p><div class="track-opts"><button class="parchment-btn" id="skyWheel2">◔ Ver la rueda del año</button></div>`; $('#skyWheel2').onclick = skyCalendar; return; } const s = SKY_STEPS[step]; info.innerHTML = `<h3>Reto ${step + 1} de ${SKY_STEPS.length}</h3><p>${s.ask}</p>${s.id === 'cinturon' && belt.length ? `<p class="season-line">Llevas ${belt.length} de 3.</p>` : ''}${msg ? `<p class="feedback">${msg}</p>` : ''}`; };
  const win = s => { found.add(s.id); s.targets.forEach(t => svg.querySelector(`.sky-star[data-star="${t}"]`).classList.add('found')); label(s.id, s.name); lines(); const first = !sky[s.id]; sky[s.id] = 1; if (first) state.knowledge += 5; if (!state.journal.includes(s.ficha)) state.journal.push(s.ficha); step = SKY_STEPS.findIndex(x => !sky[x.id]); if (step < 0) { step = SKY_STEPS.length; if (!sky.done) { sky.done = true; state.knowledge += 5; if (!state.journal.includes('lunas')) state.journal.push('lunas'); } } setHUD(); show(); info.insertAdjacentHTML('afterbegin', `<div class="sky-found"><b>✦ ${s.name}</b> <span>${fichas[s.ficha].label}</span><p>${fichas[s.ficha].text}</p><p class="journal-source">Fuente: ${(fichas[s.ficha].source || []).map(([t, u]) => `<a href="${u}" target="_blank" rel="noopener">${t}</a>`).join(' · ') || 'astronomía general'}</p></div>`); toast(`${s.name}${first ? ' · +5 saber' : ''}`); };
  const pick = id => { if (step >= SKY_STEPS.length) { const s = SKY_STEPS.find(x => x.targets.includes(id)); if (s) showFicha(s.ficha); return; } const s = SKY_STEPS[step]; if (!s.targets.includes(id)) { show(id === 'sirio' || id === 'canopo' || id === 'pleyades' || id.startsWith('belt') ? 'Esa la buscaremos luego. Pista: ' + s.hint : 'Esa no es. ' + s.hint); return; } if (s.id === 'cinturon') { if (!belt.includes(id)) { belt.push(id); svg.querySelector(`.sky-star[data-star="${id}"]`).classList.add('found'); } if (belt.length < 3) { show('¡Una más en la fila!'); return; } } win(s); };
  const near = (ev) => { const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY; const p = pt.matrixTransform(svg.getScreenCTM().inverse()); const scale = svg.getBoundingClientRect().width / 1600; const thr = Math.max(70, 26 / Math.max(scale, .05)); let best = null, bd = Infinity; Object.entries(SKY).forEach(([id, [x, y]]) => { const d = Math.hypot(p.x - x - (id === 'pleyades' ? 12 : 0), p.y - y) - (id === 'pleyades' ? 40 : 0); if (d < bd) { bd = d; best = id; } }); return bd <= thr ? best : null; };
  svg.addEventListener('pointerdown', ev => { ev.preventDefault(); const id = near(ev); if (id) pick(id); else show('Ahí no hay ninguna estrella destacada. ' + (SKY_STEPS[step] ? SKY_STEPS[step].hint : '')); });
  svg.querySelectorAll('.sky-hit').forEach(c => c.addEventListener('keydown', ev => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); pick(c.dataset.star); } }));
  $('#skyHint').onclick = () => { const s = SKY_STEPS[step]; if (!s) return; show(s.hint); s.targets.forEach(t => { const g = svg.querySelector(`.sky-star[data-star="${t}"]`); g.classList.remove('hint'); void g.getBBox(); g.classList.add('hint'); }); };
  $('#skyWheel').onclick = skyCalendar; $('#skyBack').onclick = () => hoguera('temas'); show(); }
