const KIND = { medido: ['Medido en el yacimiento', 'k-medido'], astro: ['Dato astronómico', 'k-astro'], cronica: ['Crónica', 'k-cronica'], hipotesis: ['Hipótesis', 'k-hipo'], deduccion: ['Deducción del juego', 'k-dedu'] };
