function skyCalendar(m) { nightState(); if (!state.journal.includes('lunas')) state.journal.push('lunas'); let sel = typeof m === 'number' ? m : 5; setHUD();
  const C = 200, R = 180, sector = i => { const a0 = (i * 30 - 90 - 15) * Math.PI / 180, a1 = (i * 30 - 90 + 15) * Math.PI / 180; return `M${C} ${C}L${(C + R * Math.cos(a0)).toFixed(1)} ${(C + R * Math.sin(a0)).toFixed(1)}A${R} ${R} 0 0 1 ${(C + R * Math.cos(a1)).toFixed(1)} ${(C + R * Math.sin(a1)).toFixed(1)}Z`; };
  const at = (i, r) => { const a = (i * 30 - 90) * Math.PI / 180; return [C + r * Math.cos(a), C + r * Math.sin(a)]; };
  const fill = i => [9, 10, 11, 0, 1].includes(i) ? '#2e4a5e' : [2, 3, 4].includes(i) ? '#4d5e33' : '#7a5328';
  const icon = i => { const [x, y] = at(i, 120); const k = YEAR[i].map(e => e[0]); let s = ''; if ([2, 5, 8, 11].includes(i)) s += `<circle cx="${x}" cy="${y}" r="13" fill="${i === 11 ? '#c9d4e8' : '#ffd66b'}"/>`; if ([3, 4, 6, 7].includes(i)) s += `<path d="M${x} ${y - 14}l4 10 10 1-8 7 3 10-9-6-9 6 3-10-8-7 10-1z" fill="${i === 3 ? 'none' : '#fff3c4'}" stroke="#fff3c4" stroke-width="2"/>`; if ([9, 10].includes(i)) s += `<path d="M${x - 8} ${y - 6}q4 8 0 12q-4-4 0-12M${x + 6} ${y - 10}q4 8 0 12q-4-4 0-12" fill="#9fd0ff"/>`; if ([0, 1].includes(i)) s += `<path d="M${x} ${y + 10}v-18M${x} ${y - 2}l-7-6M${x} ${y + 2}l7-6" stroke="#b9e08a" stroke-width="3" fill="none"/>`; if (k.includes('hipotesis') && ![2, 5, 8].includes(i)) s += `<circle cx="${x + 18}" cy="${y + 16}" r="4" fill="#e7a0ff"/>`; return s; };
  const moons = Array.from({ length: 12 }, (_, i) => { const [x, y] = at(i, 72); return `<circle cx="${x}" cy="${y}" r="9" fill="#f1e6c4"/><circle cx="${x + 5}" cy="${y - 2}" r="8" fill="#1d1620"/>`; }).join('');
  go(`<div class="activity-card rites-card wheel-card"><span class="eyebrow">LA NOCHE · CALENDARIO</span><h2>La rueda del año</h2><p>Cielo, campo y ritos en un mismo círculo. Toca un mes: cada dato dice si está medido en un yacimiento, si es astronomía, crónica, hipótesis o deducción del juego.</p><div class="wheel-layout"><svg class="year-wheel" viewBox="0 0 400 400" role="img" aria-label="Rueda del año con los doce meses">${MONTHS.map((_, i) => `<path class="wsec${i === sel ? ' on' : ''}" data-m="${i}" d="${sector(i)}" fill="${fill(i)}" stroke="#1d1620" stroke-width="2"/>`).join('')}${MONTHS.map((mm, i) => { const [x, y] = at(i, 160); return `<text x="${x}" y="${y + 5}" class="wlbl" text-anchor="middle">${mm[0].toUpperCase()}</text>`; }).join('')}${MONTHS.map((_, i) => icon(i)).join('')}<circle cx="${C}" cy="${C}" r="88" fill="#1d1620" stroke="#bf9860" stroke-width="2"/>${moons}<circle cx="${C}" cy="${C}" r="34" fill="url(#fireG)"/><defs><radialGradient id="fireG"><stop offset="0" stop-color="#ffe9a0"/><stop offset=".6" stop-color="#f08a2c"/><stop offset="1" stop-color="#f08a2c" stop-opacity="0"/></radialGradient></defs></svg><div class="wheel-side"><div class="month-grid">${MONTHS.map((mm, i) => `<button class="month-btn${i === sel ? ' on' : ''}" data-m="${i}" aria-pressed="${i === sel}">${mm.slice(0, 3)}</button>`).join('')}</div><div class="month-info" id="monthInfo" aria-live="polite"></div></div></div><p class="wheel-legend"><span class="k k-medido">Medido en el yacimiento</span> <span class="k k-astro">Dato astronómico</span> <span class="k k-cronica">Crónica</span> <span class="k k-hipo">Hipótesis</span> <span class="k k-dedu">Deducción del juego</span></p>${fichaHTML('lunas')}<div class="track-opts"><button class="parchment-btn" id="wRisco">Ver la luz de Risco Caído</button><button class="parchment-btn" id="wRain">Ritos de la lluvia</button><button class="parchment-btn" id="wSky">✦ Mirar el cielo</button><button class="parchment-btn" id="wFire">Volver a la hoguera</button></div></div>`, 'activity-screen', 'cielo');
  const showM = i => { sel = i; document.querySelectorAll('.wsec').forEach(p => p.classList.toggle('on', +p.dataset.m === i)); document.querySelectorAll('.month-btn').forEach(b => { b.classList.toggle('on', +b.dataset.m === i); b.setAttribute('aria-pressed', +b.dataset.m === i); }); $('#monthInfo').innerHTML = `<h3>${MONTHS[i][0].toUpperCase() + MONTHS[i].slice(1)}</h3><ul>${YEAR[i].map(([k, t, s]) => `<li><span class="k ${KIND[k][1]}">${KIND[k][0]}</span> ${t}${s && SRC[s] ? ` <a class="msrc" href="${SRC[s][1]}" target="_blank" rel="noopener" title="${SRC[s][0]}">[fuente]</a>` : ''}</li>`).join('')}</ul>`; };
  document.querySelectorAll('.wsec, .month-btn').forEach(el => el.addEventListener('click', () => showM(+el.dataset.m))); showM(sel);
  $('#wRisco').onclick = riscoCalendar; $('#wRain').onclick = rainRites; $('#wSky').onclick = skyGame; $('#wFire').onclick = () => hoguera('temas'); }
// ================= FASE 7b: arqueoastronomía dentro de «Lunas y estrellas» (hoguera) =================
// Datos calculados con PyEphem para 28° N, 15,6° O y horizonte llano (ver docs/ARQUEOASTRONOMIA.md, §6). Cada pantalla separa lo medido, la crónica y la hipótesis.
Object.assign(fichas, {
  tara: { title: 'Rayas para no olvidar: la «tara»', label: 'Crónica tardía', text: 'Marín de Cubas (1694) escribe que los antiguos canarios hacían «raías en tablas, pared o piedras; llamaban tara, y tarja aquella memoria»: marcas para llevar la cuenta. No se conserva ninguna pared de lunas identificada como tal. La cueva del juego es imaginada (inspirada en las cuevas reales); las posiciones del sol y de la luna sí están calculadas para Gran Canaria en los años 1447-1448.', source: [SRC.jimenezMUNA] },
  lunasticio: { title: 'La luna del Roque Nublo', label: 'Medido · uso por los aborígenes: hipótesis', text: 'La luna llena no sale siempre por el mismo sitio, y sus extremos cambian en un ciclo de 18,6 años. En la «parada mayor» sale lo más al sur posible. Vista desde el almogarén del Roque Bentayga, esa luna sale justo sobre el Roque Nublo y queda casi tapada por él: lo propuso el IAC y lo revisaron con observaciones Gil y Belmonte (2009). El 9 de julio de 2006 más de cien personas lo vieron. La última parada mayor fue en 2024-2025 y la próxima será en 2043. Esto se ha medido; no sabemos si lo buscaban: no hay ninguna marca demostrada para mirarlo ni ninguna crónica que lo cuente.', source: [SRC.gil2009, SRC.iacLunasticio, SRC.aagc2006, SRC.ojedaBentayga] },
  bentayga: { title: 'El ojo del Bentayga', label: 'Medido · uso por los aborígenes: hipótesis', text: 'Al pie del Roque Bentayga (Tejeda) hay un recinto excavado en la roca con cazoletas y canalillos. Mirando al este desde la gran cazoleta, en los equinoccios el sol asoma justo por una muesca en V de un pequeño promontorio, a media mañana (tiene que subir unos 21° para pasar la roca), y una cuña de luz llega a la cazoleta, todavía en sombra. Lo identificó Oswaldo González en 1993 y lo publicaron Esteban, Schlueter, Belmonte y González (1996-1997). Como la muesca es del tamaño del sol, el marcador permite fijar la fecha con un margen de alrededor de un día. Que se usara como calendario es una hipótesis.', source: [SRC.esteban1996, SRC.esteban1997, SRC.cabildoEstrella] },
  cuatropuertas: { title: 'El día más largo en Cuatro Puertas', label: 'Medido · uso por los aborígenes: hipótesis', text: 'En Montaña Bermeja (Telde), la gran cueva de cuatro bocas mira al norte. Casi todo el año el sol no entra, pero en los días cercanos al solsticio de verano, al amanecer, la luz pasa por la puerta 2 y dibuja un rectángulo en la pared del fondo (oeste) que dura pocos minutos; al atardecer entra por las puertas 3 y 4 y alcanza una pequeña cazoleta en la esquina sureste. En la cima, José Barrios propone que la sombra de una roca encaja en un signo grabado el día del solsticio (hipótesis).', source: [SRC.cabildoEstrella, SRC.teldeCuatro, SRC.barrios2017, SRC.barriosSigno] },
  angostura: { title: 'La Angostura: el gemelo invertido', label: 'Medido (2023)', text: 'En una cueva de La Angostura (Agüimes) el sol entra por una claraboya solo medio año: desde unos 10 días antes del equinoccio de otoño hasta unos 10 días después del de primavera, justo al revés que en Risco Caído. En el solsticio de invierno, los primeros rayos caen dentro de un pequeño agujero hecho y pintado en la pared. Lo midieron durante años Caballero Suárez y Esteban (2023). Su posible uso como calendario sigue siendo una hipótesis.', source: [SRC.angostura2023] },
  debate: { title: '¿Calendario o templo?', label: 'Pregunta abierta', text: 'Que la luz entra en ciertas fechas en Risco Caído, el Bentayga, Cuatro Puertas o La Angostura está medido. Para qué servía, no. Unos investigadores proponen que Risco Caído fue un calendario lunisolar, quizá útil para el campo (Cuenca et al. 2018; IAU 2019). Otros, como Caballero Suárez, creen que estas cuevas eran más bien templos, y Caballero y Esteban (2023) piden publicaciones técnicas más detalladas sobre el marcador de Risco Caído. ICOMOS (2019) avisa de que «es difícil establecer con certeza» si es correcto llamarlos «marcadores astronómicos». Es una pregunta abierta.', source: [SRC.riscoMAA, SRC.riscoIAU, SRC.angostura2023, SRC.templosSolares, SRC.riscoICOMOS] }
});
function wallState() { const n = nightState(); if (typeof n.nights !== 'number') n.nights = 0; const w = n.wall && typeof n.wall === 'object' ? n.wall : (n.wall = {}); if (typeof w.moon !== 'number') w.moon = 0; w.moon = Math.max(0, Math.min(13, Math.floor(w.moon))); if (typeof w.half !== 'boolean') w.half = false; if (w.mode !== 'noche' && w.mode !== 'seguido') w.mode = 'noche'; if (typeof w.lastNight !== 'number') w.lastNight = -1; if (!w.q || typeof w.q !== 'object') w.q = {}; if (typeof w.done !== 'boolean') w.done = w.moon >= 13; if (typeof w.read !== 'boolean') w.read = false; if (typeof w.nublo !== 'boolean') w.nublo = false; if (w.opinion === undefined) w.opinion = null;
  if (!n.bentayga || typeof n.bentayga !== 'object') n.bentayga = {}; ['done', 'moved'].forEach(k => { if (typeof n.bentayga[k] !== 'boolean') n.bentayga[k] = false; });
  if (!n.cuatro || typeof n.cuatro !== 'object') n.cuatro = {}; ['done', 'am', 'pm'].forEach(k => { if (typeof n.cuatro[k] !== 'boolean') n.cuatro[k] = false; }); return w; }
function migrateF7b() { wallState(); }
