const zig = (pts, a = 9) => { const o = []; for (let s = 0; s < pts.length - 1; s++) { const [x1, y1] = pts[s], [x2, y2] = pts[s + 1], L = Math.hypot(x2 - x1, y2 - y1), n = Math.max(2, Math.round(L / 22)), nx = -(y2 - y1) / L, ny = (x2 - x1) / L; for (let i = 0; i < n; i++) { const t = i / n, k = i % 2 ? a : -a; o.push(`${(x1 + (x2 - x1) * t + nx * k).toFixed(1)},${(y1 + (y2 - y1) * t + ny * k).toFixed(1)}`); } } o.push(pts[pts.length - 1].join(',')); return `<polyline points="${o.join(' ')}" fill="none" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/>`; };
