function archArt(cx, car) { let s = ''; for (let i = 0; i < 14; i++) { const t = (i / 13 - .5) * 2.5, x = cx + 165 * Math.sin(t), y = 450 - 165 * Math.cos(t), a = Math.abs(t), w = a > .8 ? 40 : a > .45 ? 32 : 24, h = a > .8 ? 46 : a > .45 ? 36 : 30; s += `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${(t * 57.3).toFixed(1)})"><rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="9" fill="#f6ecd2" stroke="${INK}" stroke-width="4"/>${car.includes(i) ? `<circle r="${w > 30 ? 9 : 6}" cx="2" cy="-3" fill="#4a2c17"/>` : ''}</g>`; } return s; }
