    document.querySelectorAll('[data-b]').forEach(x => { const j = +x.dataset.b; x.setAttribute('aria-pressed', j === i); x.disabled = j > H.step && !H.done; x.textContent = `${j < H.step || H.done ? '✔ ' : ''}${j + 1}. ${BONES[j].tab}`; });
