    if ($('#hNext')) $('#hNext').onclick = () => { if (i >= H.step && !H.done) H.step = i + 1; if (i < 4) { i++; phase = 'look'; } else { phase = 'fin'; if (!H.done) { H.done = true; H.step = 5; state.knowledge += 12; addFicha('huesos'); setHUD(); toast('Ficha nueva: cuidar se ve en los huesos · +12 saber · historia nueva para otra noche'); } } save(); draw(); };
