// --- A · ¿Qué cuenta la crónica? ---
const ISL = { EH: ['El Hierro', 120, 360], LP: ['La Palma', 170, 170], LG: ['La Gomera', 285, 320], TF: ['Tenerife', 430, 270], GC: ['Gran Canaria', 600, 350], FV: ['Fuerteventura', 735, 245], LZ: ['Lanzarote', 800, 110] };
const CASES = [
  { id: 'herida', title: 'Un luchador vuelve con una herida', isl: 'GC', q: 'Tras una lucha con reglas, un joven vuelve con una herida profunda. ¿Qué cuenta la crónica que hacían?', opts: [['Meter junco majado mojado en manteca muy caliente, para quemar la herida.', 1], ['Coser la herida con un tendón.', 0, 'Sabían coser pieles con tendones finísimos, pero no hay ninguna herida cosida documentada.'], ['Ponerle hojas de borraja calientes.', 0, '¡Trampa! La borraja es folclore moderno: no consta que fuera aborigen.']], where: `${kb('gc', 'Gran Canaria')} Abreu Galindo, libro II (crónica, h. 1600).`, today: 'Una herida la mira una persona adulta; si es grave, 112. Quemar una herida provoca quemaduras e infecciones.' },
  { id: 'tripa', title: 'Dolor de tripa y diarrea', isl: 'TF', q: 'Alguien tiene dolor de tripa y diarrea («cámaras», decían los cronistas). ¿Qué cuenta la fuente?', opts: [['El chacerquén: una miel hecha con frutos de mocán.', 1], ['Beber agua de Firgas.', 0, '¡Trampa! La fama de esas aguas es de los balnearios del siglo XIX.'], ['Polvo de sangre de drago.', 0, 'Eso lo cuentan fuentes europeas posteriores, no los cronistas de los aborígenes.']], where: `${kb('otra', 'Otra isla: Tenerife')} Abreu Galindo, libro III. En Gran Canaria el mocán solo aparece como comida.`, today: 'Beber agua a menudo y avisar a una persona adulta o al médico. No se toman plantas ni frutos silvestres.' },
  { id: 'costado', title: 'Dolor de costado', isl: 'TF', q: 'Una persona tiene un fuerte dolor de costado. Además del chacerquén, ¿qué otro remedio cuentan las crónicas?', opts: [['Una sangría: sacar un poco de sangre con una tabona (piedra afilada).', 1], ['Frotar con leche de tabaiba.', 0, '¡Peligro! El látex de la tabaiba amarga es tóxico, y ninguna crónica cuenta ese remedio.'], ['Un baño en el mar.', 0, 'Los baños de mar aparecen en las crónicas, pero no como cura del costado.']], where: `${kb('otra', 'Otra isla: Tenerife')} Abreu, Espinosa y Viana; también en Fuerteventura. ${kb('tardia', 'Crónica tardía')} En Gran Canaria solo lo menciona Sosa (1678), como costumbre de su época.`, today: 'Sangrar es peligroso y no cura: se pierde sangre y hay infecciones. El dolor fuerte lo ve el médico.' },
  { id: 'fiebre', title: 'Frío y fiebre', isl: 'EH', q: 'Alguien tiembla de frío y tiene fiebre. ¿Qué cuenta la crónica?', opts: [['Untarse con manteca, abrigarse bien y sudar.', 1], ['Bañarse en las aguas de Teror.', 0, '¡Trampa! Es folclore moderno de los balnearios del siglo XIX.'], ['Mascar tabaiba amarga.', 0, '¡Peligro! La tabaiba amarga es tóxica.']], where: `${kb('otra', 'Otra isla: El Hierro')} Abreu Galindo, capítulos de El Hierro.`, today: 'Con fiebre: descansar, beber agua y que una persona adulta llame al centro de salud.' },
  { id: 'brazo', title: 'Un brazo roto', isl: 'GC', q: 'Alguien se ha caído por un risco y se ha roto el brazo. ¿Qué se ha encontrado?', opts: [['Tablillas de tabaiba, vendas de junco y cuero, y resina.', 1], ['Dejar el brazo suelto para que se mueva.', 0, 'Si el hueso se mueve, no suelda bien: los huesos curados indican que inmovilizaban.'], ['Quemarlo con un hierro al rojo.', 0, 'No tenían hierro: sus herramientas eran de piedra, hueso y madera.']], where: `${kb('gc', 'Gran Canaria')} ${kb('arq', 'Arqueología, no crónica')} La férula de Guayadeque, descrita en 1900 ${kb('nover', 'no verificada hoy')}.`, today: 'No lo muevas ni intentes enderezarlo: el personal sanitario lo inmoviliza. Si es grave, 112.' },
  { id: 'bebe', title: 'Ha nacido un bebé', isl: 'TF', q: 'Acaba de nacer un bebé. ¿Qué cuenta la crónica?', opts: [['Lo lavaban mujeres que se dedicaban solo a eso.', 1], ['Lo untaban con sangre de drago.', 0, 'No hay ninguna fuente que lo cuente.'], ['Lo bañaban en las aguas de Azuaje.', 0, '¡Trampa! Es folclore moderno de los balnearios del siglo XIX.']], where: `${kb('otra', 'Otra isla: Tenerife')} Crónicas de Tenerife (no hay dato de Gran Canaria).`, today: 'Hoy cuidan a la madre y al bebé las matronas y el personal sanitario.' }];
function islandsSVG(pins, cur) { const P = { EH: 'M-34 0Q-30-20 0-22Q30-20 34 4Q10 0 0 18Q-20 14-34 0Z', LP: 'M0-55Q24-30 20 10Q14 50 0 58Q-14 40-22 0Q-20-36 0-55Z', LG: 'M-30 0Q-28-28 0-30Q28-28 30 0Q26 28 0 30Q-28 28-30 0Z', TF: 'M-90 30Q-70-10-20-30Q40-50 90-40Q60-10 30 20Q-20 50-90 30Z', GC: 'M-55 0Q-52-50 0-55Q52-50 55 0Q50 52 0 55Q-52 50-55 0Z', FV: 'M-10-100Q30-90 34-40Q30 20-20 90Q-44 100-30 60Q-6 0-10-100Z', LZ: 'M-6-58Q30-50 26-10Q18 40-12 58Q-30 40-24 0Q-22-40-6-58Z' };
  return `<g class="isl-map" transform="translate(10 10) scale(1.25)"><rect x="30" y="30" width="840" height="530" rx="22" fill="#f3e3bf" fill-opacity=".95" stroke="#8a5a33" stroke-width="5"/><path d="M30 120Q300 90 870 150M30 300Q400 260 870 330" stroke="#bfa17a" stroke-width="2" fill="none" opacity=".6"/>${Object.entries(ISL).map(([k, [n, x, y]]) => `<path transform="translate(${x + 30} ${y + 30})" d="${P[k]}" fill="${k === 'GC' ? '#e9c46a' : '#cdb48a'}" stroke="#6b4a32" stroke-width="4"/><text x="${x + 30}" y="${y + (k === 'LZ' ? 110 : k === 'FV' ? 140 : k === 'LP' ? 108 : 98)}" class="med-lbl s" text-anchor="middle">${n}</text>`).join('')}
  ${pins.map(([c, j]) => { const [, x, y] = ISL[c.isl], n = pins.filter(p => p[0].isl === c.isl).indexOf(pins.find(p => p[0] === c)), px = x + 30 + (n - 1) * 46, py = y + 30 - 4; return `<g class="pin${c === cur ? ' cur' : ''}"><circle cx="${px}" cy="${py}" r="22" fill="${c.isl === 'GC' ? '#2a7f73' : '#d2662f'}" stroke="#fff6dc" stroke-width="4"/><text x="${px}" y="${py + 9}" class="pin-n" text-anchor="middle">${j + 1}</text></g>`; }).join('')}
  <circle cx="70" cy="530" r="12" fill="#2a7f73"/><text x="90" y="538" class="med-lbl s">Gran Canaria</text><circle cx="290" cy="530" r="12" fill="#d2662f"/><text x="310" y="538" class="med-lbl s">otra isla</text><text x="850" y="538" class="med-lbl s" text-anchor="end">esquema, no a escala</text></g>`; }
function cronicaGame() { const m = medState(), C = m.cronica; let i = CASES.findIndex(c => !C.cases[c.id]); if (i < 0) i = 0; let phase = C.done ? 'fin' : 'r'; setHUD();
  go(`<div class="mini-wrap astro-wrap med-wrap"><div class="mini-head"><span class="eyebrow">REMEDIOS Y HUESOS · CUEVA DE FAYNA</span><h2>¿Qué cuenta la crónica?</h2><p>Seis casos. Elige lo que cuenta la fuente (no lo que harías tú), adivina de qué isla es el dato y mira qué se hace hoy.</p></div>
  <div class="mini-stage astro-stage med-stage"><svg class="astro-svg" id="aSvg" viewBox="0 0 1600 900" role="img" aria-label="Interior de una cueva con junco, manteca, mocanes y resina, y un mapa esquemático de las islas con los casos"><image href="img/medicina/cueva_remedios.webp" width="1600" height="900" preserveAspectRatio="xMidYMid slice"/><g id="aMap"></g></svg></div>
  <div class="astro-side"><div class="sky-info med-info" id="aInfo" aria-live="polite"></div></div>
  <div class="mini-controls"><button class="parchment-btn" id="aFicha">Ficha: el mapa de los remedios</button><button class="parchment-btn" id="aBack">Volver a la hoguera</button></div>
  <p class="medical-warning">${MEDICAL_WARNING}</p></div>`, 'activity-screen astro-screen med-screen', 'hoguera');
  const draw = (msg = '') => { const c = CASES[i], pins = CASES.map((x, j) => [x, j]).filter(([x]) => C.cases[x.id] || (x === c && phase === 'hoy')); $('#aMap').innerHTML = islandsSVG(pins, phase === 'hoy' ? c : null);
    let t; if (phase === 'fin') { const gc = CASES.filter(x => x.isl === 'GC').length; t = `<h3>El mapa de los remedios</h3><p>De ${CASES.length} casos, solo <b>${gc}</b> son de Gran Canaria, y uno (la férula) lo cuenta la arqueología, no una crónica. El resto viene de <b>otras islas</b>.</p><p>${kb('dedu', 'Qué aprendemos')} No se puede contar la medicina de Gran Canaria con datos de Tenerife o El Hierro sin decirlo.</p><button class="parchment-btn" id="aAgain">Repasar los casos</button>`; }
    else { t = `<h3>Caso ${i + 1}/6 · ${c.title}</h3>`;
      if (phase === 'r') t += `<p><b>${c.q}</b></p><div class="med-opts">${mix(c.opts.length, i + 1).map(j => `<button class="choice-btn ar" data-j="${j}">${c.opts[j][0]}</button>`).join('')}</div>`;
      else if (phase === 'i') t += `<p>✔ ${c.opts[0][0]}</p><p><b>¿De qué isla es este dato?</b></p><div class="seg"><button class="parchment-btn ai" data-i="GC">Gran Canaria</button><button class="parchment-btn ai" data-i="otra">Otra isla</button></div>`;
      else t += `<p>✔ ${c.opts[0][0]}</p><p>${c.where}</p><p class="today-box">${kb('hoy', '¿Y hoy?')} ${c.today}</p><button class="parchment-btn" id="aNext">${Object.keys(C.cases).length >= 6 ? 'Ver el mapa ▶' : 'Siguiente caso ▶'}</button>`;
      if (msg) t += `<p class="feedback">${msg}</p>`; }
    $('#aInfo').innerHTML = t;
    document.querySelectorAll('.ar').forEach(x => x.onclick = () => { const o = c.opts[+x.dataset.j]; if (o[1]) { phase = 'i'; draw(); } else { draw(o[2]); document.querySelector(`.ar[data-j="${x.dataset.j}"]`).disabled = true; } });
    document.querySelectorAll('.ai').forEach(x => x.onclick = () => { const ok = (x.dataset.i === 'GC') === (c.isl === 'GC'); C.cases[c.id] = 1; phase = 'hoy'; save(); draw(ok ? '¡Correcto!' : `No: es de ${c.isl === 'GC' ? 'Gran Canaria' : `otra isla (${ISL[c.isl][0]})`}.`); });
    if ($('#aNext')) $('#aNext').onclick = () => { const nx = CASES.findIndex(x => !C.cases[x.id]); if (nx < 0) { phase = 'fin'; if (!C.done) { C.done = true; state.knowledge += 8; addFicha('mapa_remedios'); setHUD(); toast('Ficha nueva: el mapa de los remedios · +8 saber'); } } else { i = nx; phase = 'r'; } save(); draw(); };
    if ($('#aAgain')) $('#aAgain').onclick = () => { C.cases = {}; i = 0; phase = 'r'; save(); draw(); }; };
  $('#aFicha').onclick = () => { if (C.done) showFicha('mapa_remedios'); else toast('Termina los seis casos para conseguir esta ficha.'); }; $('#aBack').onclick = () => hoguera('temas'); draw(); }
// --- B · Herbario de Fayna: solo fichas del Cuaderno (sin recetas) ---
const ico = (src, alt) => `<img src="img/iconos/${src}.webp" alt="${alt}" width="96" height="96">`;
const svgIco = (body, alt) => `<svg viewBox="0 0 96 96" role="img" aria-label="${alt}">${body}</svg>`;
const WARN_TRI = '<path d="M70 52l18 32H52z" fill="#ffd23f" stroke="#7a1f12" stroke-width="4" stroke-linejoin="round"/><path d="M70 63v10M70 78v1" stroke="#7a1f12" stroke-width="5" stroke-linecap="round"/>';
const HERB = [['hb_mocan', ico('mocan', 'Frutos de mocán'), 'otra'], ['hb_junco', ico('junco', 'Junco'), 'gc'], ['drago', ico('drago', 'Resina de drago'), 'tardia'], ['hb_manteca', ico('manteca', 'Manteca de cabra'), 'gc'], ['hb_laurel', ico('laurel', 'Laurel'), 'hipo'], ['hb_almacigo', svgIco('<path d="M48 90V50" stroke="#6b4a32" stroke-width="8"/><circle cx="48" cy="34" r="26" fill="#6f8f3a"/><circle cx="30" cy="44" r="14" fill="#5f7f2f"/><circle cx="66" cy="44" r="14" fill="#5f7f2f"/><path d="M56 62q6 8 0 12q-6-4 0-12z" fill="#e0a43a"/>', 'Almácigo'), 'otra'],
  ['hb_tabaiba', svgIco(`<path d="M40 90V60M40 60L24 40M40 60L56 38M24 40L16 26M24 40L32 24M56 38L50 22M56 38L66 26" stroke="#7d6a4a" stroke-width="6" stroke-linecap="round" fill="none"/>${[[16, 22], [32, 20], [50, 18], [66, 22]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="9" fill="#8fae4a"/>`).join('')}${WARN_TRI}`, 'Tabaiba amarga, con aviso de peligro'), 'tox'],
  ['hb_cardon', svgIco(`<path d="M30 90V30q0-10 8-10t8 10v60M46 60h10V40q0-8 7-8t7 8v26q0 10-12 10H46M30 64H22q-10 0-10-10V44q0-7 6-7t6 7v14h6" fill="#6f8f3a" stroke="#3f5a1f" stroke-width="3"/>${WARN_TRI}`, 'Cardón, con aviso de peligro'), 'tox'],
  ['hb_borraja', svgIco(`<path d="M48 90V44" stroke="#4f7a2a" stroke-width="6"/><ellipse cx="32" cy="70" rx="16" ry="8" fill="#6f9a3a" transform="rotate(-25 32 70)"/>${[[48, 30], [28, 40], [68, 40]].map(([x, y]) => `<g transform="translate(${x} ${y})">${[0, 72, 144, 216, 288].map(a => `<ellipse rx="5" ry="11" cy="-9" fill="#4a6fd8" transform="rotate(${a})"/>`).join('')}<circle r="4" fill="#222"/></g>`).join('')}`, 'Borraja (trampa: folclore moderno)'), 'folk'],
  ['hb_aguas', svgIco('<path d="M48 10Q72 44 72 60a24 24 0 0 1-48 0Q24 44 48 10z" fill="#7ec3e8" stroke="#2f6f9a" stroke-width="4"/><path d="M38 58q0 12 10 14" stroke="#fff" stroke-width="5" fill="none" stroke-linecap="round"/>', 'Aguas de manantial (trampa: folclore moderno)'), 'folk']];
const HERB_TAG = { gc: 'Gran Canaria', otra: 'otra isla', tardia: 'más tarde', hipo: 'no es medicina', tox: '⚠ peligro', folk: 'folclore moderno' };
function herbario(back) { const m = medState(); const card = ([k, ic, c]) => `<button class="herb-card${m.herb[k] ? ' seen' : ''}" data-k="${k}" aria-label="${fichas[k].title}">${ic}<span class="herb-name">${fichas[k].title.replace(/ · .*/, '')}</span>${kb(c, HERB_TAG[c])}</button>`;
  openModal(`<div class="herb-modal"><span class="eyebrow">REMEDIOS Y HUESOS</span><h2>Herbario de Fayna</h2><p>Cada carta es una ficha del Cuaderno: ¿comida, remedio según una fuente… o peligro y trampa? <b>Aquí no hay recetas.</b></p><p class="medical-warning">${MEDICAL_WARNING}</p><div class="herb-grid">${HERB.map(card).join('')}</div><div id="herbDetail" aria-live="polite"></div>${back ? '<button class="parchment-btn" id="herbBack">Volver al Cuaderno</button>' : ''}</div>`, 'wide');
  document.querySelectorAll('.herb-card').forEach(b => b.onclick = () => { const k = b.dataset.k; if (!m.herb[k]) { m.herb[k] = 1; state.knowledge += 1; } addFicha(k); save(); setHUD(); b.classList.add('seen'); $('#herbDetail').innerHTML = fichaHTML(k); $('#herbDetail').scrollIntoView({ block: 'nearest' }); });
  if ($('#herbBack')) $('#herbBack').onclick = back; }
// ===== fin FIX (fase 8) =====
$('#rotateContinue').onclick = () => { document.body.classList.add('portrait-ok'); };
// FIX (móvil): instalación como app sin conexión (manifest + service worker) SOLO si se sirve por http(s); abierto como archivo local (file://) no se carga nada de esto.
if (location.protocol.startsWith('http')) { const manifest = document.createElement('link'); manifest.rel = 'manifest'; manifest.href = 'manifest.webmanifest'; document.head.append(manifest); if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(() => { /* sin modo sin conexión */ }); }
// FIX (final): al volver del silbo (index.html?volver=mapa) se continúa la partida directamente en el mapa.
const savedOnLoad = loadSave(); if (new URLSearchParams(location.search).get('volver') === 'mapa' && savedOnLoad) { Object.assign(state, savedOnLoad); resume(); if (state.done.silbo && !sessionStorage.getItem('silboAviso')) { sessionStorage.setItem('silboAviso', '1'); toast('Nueva ficha en el Cuaderno: El silbo gomero'); } } else intro();
